"""Reproducible assembly of session-authored ORIGINAL drafts; never publishes.

Rows are authored problems, not random substitutions into a question template.
Run from the worktree root. Validation is a separate TypeScript command.
"""
import ast
import json
import operator
import random
from pathlib import Path

BASE = Path('content/vihaan-scholarship/expansion-500')
ITEMS = []
COUNTS = {}
OPTION_ORDER = random.Random(20261116)
OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.Pow: operator.pow, ast.Mod: operator.mod}

def calculate(expression):
    def visit(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in OPS:
            return OPS[type(node.op)](visit(node.left), visit(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
            return -visit(node.operand)
        raise ValueError(expression)
    return visit(ast.parse(expression.strip(), mode='eval').body)

def fmt(value):
    return str(int(value)) if float(value).is_integer() else str(round(value, 6))

def add(subject, skill, difficulty, prompt, choices, solution, topic=None, stimulus=None, expression=None):
    # First choice in authoring data is the intended response. Rotate storage
    # positions deterministically, so the answer position is not predictable.
    COUNTS[subject] = COUNTS.get(subject, 0) + 1
    serial = COUNTS[subject]
    prefix = dict(numeracy='m', numerical_reasoning='n', verbal_reasoning='v', reading='r', writing='w')[subject]
    identifier = f'vihaan-e500-{prefix}{serial:03}'
    shift = OPTION_ORDER.randrange(4)
    options = [{'id': chr(97+i), 'text': str(choices[(i-shift) % 4])} for i in range(4)] if choices else []
    strands = {'maths-algebra': 'Algebra', 'maths-directed-numbers': 'Directed Numbers',
               'maths-fractions-decimals': 'Fractions and Decimals', 'maths-geometry': 'Geometry and Measurement',
               'maths-percentages': 'Percentages', 'maths-probability': 'Probability',
               'maths-ratios-rates': 'Ratios and Rates'}
    strand = strands.get(skill, dict(numerical_reasoning='Numerical Reasoning', verbal_reasoning='Verbal Reasoning', reading='Reading Comprehension', writing='Written Expression').get(subject))
    q = dict(id=identifier, type='essay' if subject=='writing' else 'reading_comprehension' if stimulus else 'multiple_choice',
             yearLevel=6, examStyle='scholarship_style', status='draft', origin='original_seed', prompt=prompt,
             options=options, visuals=[], answerKey={'kind':'single_option','optionId':chr(97+shift)} if choices else
             {'kind':'manual','rubric':'Use scholarship-written-expression v1: assess punctuation, creativity, construction, grammar, spelling and relevance separately on the 1 to 5 scale. No single model response is required.'},
             explanation=' '.join(solution), metadata=dict(subject=subject, strand=strand, topic=topic or skill.replace('-', ' '),
             skill='scholarship.'+skill, difficulty=dict(E='easy', M='medium', C='challenging')[difficulty], marks=1,
             estimatedTimeSeconds=900 if subject=='writing' else dict(E=60,M=90,C=150)[difficulty] + (60 if stimulus else 0),
             tags=['vihaan-expansion','year-5-6-stretch']+(['manual-assessment'] if subject=='writing' else []),
             locale='en-AU', source='original', schemaVersion=1))
    if stimulus:
        q['stimulus'] = dict(title=stimulus[0], body=stimulus[1], attribution='MindMosaic original')
    item = dict(question=q, workedSolution=solution,
                reviewFocus=['Independently solve without the key; check each alternative and the stated conditions.',
                             'Review originality, vocabulary, difficulty and time for an above-average Year 5/6 learner.'],
                writingGuidance=None)
    if subject=='writing':
        item['writingGuidance']=dict(rubricId='scholarship-written-expression',rubricVersion=1,
            successCriteria=solution+['Edit sentence boundaries, punctuation and Australian spelling.'],assessmentMode='human_only')
    if expression is not None:
        result = calculate(expression)
        assert abs(float(choices[0])-result)<0.000001, (identifier, choices, expression, result)
        # Review-only arithmetic evidence, outside the canonical question and its metadata.
        item['arithmeticCheck'] = dict(expression=expression, expected=fmt(result))
    ITEMS.append(item)

def numeric(subject, rows):
    for row in rows.strip().splitlines():
        skill, difficulty, stem, expression, distractors, working = row.split('|')
        answer = fmt(calculate(expression))
        solution = working.split('~')
        assert len(solution)>=2
        add(subject, skill, difficulty, stem, [answer]+distractors.split(';'), solution, expression=expression)

def verbal(rows):
    for row in rows.strip().splitlines():
        skill, difficulty, stem, choices, working = row.split('|')
        add('verbal_reasoning', skill, difficulty, stem, choices.split(';'), working.split('~'))

def reading(title, body, rows):
    for row in rows.strip().splitlines():
        skill, difficulty, stem, choices, working = row.split('|')
        add('reading', 'rc-'+skill, difficulty, stem, choices.split(';'), working.split('~'), stimulus=(title,body.strip()))

# Mathematics: each row has its own context, quantities, reasoning and working.
numeric('numeracy', r'''
maths-fractions-decimals|E|A ribbon is 3.6 m long. Eva cuts off 0.85 m and then 1.25 m. How many metres remain?|3.6-0.85-1.25|1.4;1.6;2.1|The two cuts total 0.85 + 1.25 = 2.10 metres.~Subtract 2.10 from 3.60 to leave 1.50 metres; align the decimal places.
maths-fractions-decimals|E|Five identical bottles each hold 0.45 litres. How many litres do they hold altogether?|5*0.45|0.9;2.05;2.5|Multiply the capacity of one bottle by five.~Five lots of 0.45 litres give 2.25 litres, not 0.90 litres from adding the two numbers.
maths-fractions-decimals|M|A recipe uses 3/4 cup of oats for 6 biscuits. How many cups are needed for 10 biscuits at the same rate?|3/4/6*10|1;1.5;2|One biscuit uses (3/4) divided by 6, which is 1/8 cup.~Ten biscuits require 10/8 = 1.25 cups; scaling by four extra biscuits is different from adding four cups.
maths-fractions-decimals|C|One third of a tank is full. After 18 litres are added it is five sixths full. What is its total capacity in litres?|18/(5/6-1/3)|27;30;54|The added fraction is 5/6 minus 1/3 = 1/2 of the tank.~If half the tank holds 18 litres, its full capacity is 36 litres.
maths-fractions-decimals|M|Tari walks 2/5 of a 15 km trail before lunch and another 1/3 of the whole trail afterwards. How many kilometres remain?|15*(1-2/5-1/3)|3;5;6|Both fractions refer to the whole trail: 2/5 + 1/3 = 11/15.~Eleven kilometres have been walked, leaving 4 kilometres.
maths-fractions-decimals|C|A school orders 7.5 kg of clay. Each sculpture uses 3/8 kg. Two sculptures break after being made and cannot be reused. How many completed sculptures remain?|7.5/(3/8)-2|16;18.75;20|Divide 7.5 by 3/8, or multiply 7.5 by 8/3, to get 20 sculptures made.~The two broken sculptures still used clay, so 20 minus 2 gives 18 completed sculptures.
maths-fractions-decimals|M|A runner covers 1.75 km in the morning and 2.6 km in the evening on each of four days. What is the total distance in kilometres?|4*(1.75+2.6)|8.7;14.4;18.4|Add the two daily distances to get 4.35 km.~Multiply by four days to get 17.4 km; both runs occur on every day.
maths-fractions-decimals|C|A class uses 5/12 of a paper roll on Monday and 3/7 of the remainder on Tuesday. What fraction of the original roll is still unused? Give a decimal to six places if necessary.|(1-5/12)*(1-3/7)|0.25;0.416667;0.571429|After Monday, 7/12 of the roll remains.~Tuesday leaves 4/7 of that amount: (7/12) times (4/7) = 1/3, or 0.333333 to six decimal places.
maths-fractions-decimals|M|Which decimal is exactly halfway between 0.38 and 0.64?|(0.38+0.64)/2|0.13;0.5;0.52|The gap is 0.64 minus 0.38 = 0.26.~Half the gap is 0.13; add it to 0.38 to obtain 0.51.
maths-fractions-decimals|C|Milo spends 2/5 of his savings on a helmet and $18 on gloves. He has $42 left. How many dollars did he start with?|(18+42)/(1-2/5)|75;90;150|After buying the helmet, the remaining 3/5 covers both the gloves and the final $42.~Thus 3/5 of the savings is $60, so the original savings were 60 times 5/3 = $100.
maths-fractions-decimals|M|Two ropes measure 4 1/2 m and 3 3/4 m. Joining them uses 1/4 m from each rope in a knot. What is the usable length in metres?|4.5+3.75-2*0.25|7.5;8;8.25|Before joining, the ropes total 8.25 metres.~Two quarter-metre lengths are used by the knot, leaving 7.75 metres.
maths-fractions-decimals|C|A printer finishes 0.35 of a job in the first hour and 0.4 of the remaining job in the second. What percentage of the whole job is still unfinished?|(1-0.35)*(1-0.4)*100|25;26;65|The first hour leaves 0.65 of the job.~The second hour leaves 0.6 of that remainder, so 0.65 times 0.6 = 0.39, or 39%.
maths-fractions-decimals|M|A parcel weighs 2.08 kg including a box weighing 0.275 kg. What is the mass of the contents in kilograms?|2.08-0.275|1.705;1.815;2.355|Write the total as 2.080 kg to align thousandths.~Subtract 0.275 kg to obtain 1.805 kg; adding would include the box twice.
maths-fractions-decimals|M|A relay covers 8 km. The first runner covers 3/8 of it; the second covers 2/5 of what remains. How many kilometres must the third runner cover?|8*(1-3/8)*(1-2/5)|2;4;5|The first runner covers 3 km, leaving 5 km.~The second covers 2/5 of 5 = 2 km, so the last runner has 3 km left.
maths-fractions-decimals|M|A shop divides 6.3 kg of rice equally among 14 bags. How many kilograms are in each bag?|6.3/14|0.35;0.5;0.9|There are 6300 grams in 6.3 kg.~Dividing by 14 gives 450 grams per bag, equivalent to 0.45 kg.
maths-percentages|E|A $60 game is reduced by 15%. What is its sale price in dollars?|60*(1-15/100)|9;45;55|Ten per cent is $6 and five per cent is $3, so the reduction is $9.~Subtract the reduction from $60 to get $51; $9 is the saving rather than the price.
maths-percentages|E|Of 80 students, 25% travel by bus. How many students do not travel by bus?|80*(1-25/100)|20;55;75|Twenty-five per cent is one quarter, so 20 students travel by bus.~Subtract 20 from 80 to find the 60 students who use other travel arrangements.
maths-percentages|M|A club grows from 48 members to 60. What is the percentage increase?|100*(60-48)/48|12;20;30|The increase is 12 members.~Compare 12 with the original 48: 12/48 = 1/4 = 25%, rather than dividing by the final membership.
maths-percentages|C|A bicycle price rises by 20% and is then reduced by 20%. What percentage of the original price is the final price?|1.2*0.8*100|80;100;104|Start with an imaginary price of $100; the rise makes it $120.~The later reduction is $24, leaving $96, or 96% of the original price. Equal percentage changes have different bases.
maths-percentages|C|After a 30% reduction, a jacket costs $63. What was its original price in dollars?|63/0.7|81.9;93;210|The sale price represents 70% of the original.~Divide 63 by 0.7 to obtain $90; adding 30% of $63 would use the wrong base.
maths-percentages|M|A pupil answers 34 of 40 questions correctly. What percentage are incorrect?|100*(40-34)/40|6;17.5;85|There are 6 incorrect responses out of 40.~Calculate 6/40 times 100 = 15%; 85% is the proportion correct.
maths-percentages|C|A fundraiser reaches 65% of its target. Another $210 takes it to 95%. What is the target in dollars?|210/(0.95-0.65)|600;650;735|The extra $210 is 30% of the target.~Divide by 0.30 to find $700; the target is the whole amount, not the money already raised.
maths-percentages|M|A water bill of $120 includes a fixed fee of $20. Usage charges alone rise by 10%. What is the new total bill in dollars?|20+(120-20)*1.1|122;132;142|Only the $100 usage part rises, by $10.~Add the unchanged $20 fee to $110 to obtain a $130 bill.
maths-percentages|C|A library has 600 books, 40% of them fiction. It receives 100 new fiction books and no others. What percentage of its books are now fiction? Round to the nearest whole per cent.|49|40;48;57|There were 240 fiction books; now there are 340 out of 700 books.~340 divided by 700 is about 48.57%, which rounds to 49%. The denominator also grows.
maths-percentages|M|A team won 60% of its first 15 matches. It then won the next 5 matches. How many matches has it won altogether?|0.6*15+5|9;12;15|Sixty per cent of 15 is 9 wins.~Add the five later wins to get 14; do not take 60% of all 20 matches.
maths-percentages|C|A $150 order attracts a 12% discount, then a $9 delivery fee. A voucher pays $20 of the final bill. How much does the buyer pay in dollars?|150*0.88+9-20|112;123;139|The discounted goods cost 150 times 0.88 = $132.~Add delivery to get $141, then subtract the $20 voucher to get $121.
maths-percentages|M|A seed tray has 120 seeds. Ten per cent fail to sprout and one sixth of the sprouts wilt. How many healthy seedlings remain?|120*0.9*(1-1/6)|88;92;100|After sprouting, 90% of 120 = 108 seedlings remain.~One sixth of 108 is 18; subtracting leaves 90 healthy seedlings.
maths-ratios-rates|E|Four exercise books cost $14 at a constant unit price. What do six cost in dollars?|14/4*6|17.5;20;24|Divide $14 by four to get $3.50 per book.~Six books cost 6 times $3.50 = $21; adding two dollars would not preserve the rate.
maths-ratios-rates|M|A cordial mix uses 2 parts concentrate to 7 parts water. How many millilitres of concentrate are in 1350 mL of the mix?|1350*2/9|270;350;1050|There are nine equal parts in the whole mixture.~Each part is 150 mL, so two parts of concentrate total 300 mL.
maths-ratios-rates|C|Three taps together fill 72 litres in 4 minutes. All taps have equal flow. How many minutes will two taps take to fill 90 litres?|90/(72/4/3*2)|5;6;10|Together the taps deliver 18 litres per minute, so each delivers 6.~Two taps deliver 12 litres per minute; 90 divided by 12 = 7.5 minutes.
maths-ratios-rates|M|A cyclist travels 18 km in 45 minutes at a steady speed. How far does she travel in 70 minutes, in kilometres?|18/45*70|24;27;30|The rate is 18/45 = 0.4 kilometres per minute.~Multiply by 70 to get 28 km, keeping both times in minutes.
maths-ratios-rates|C|A map scale is 1:25000. A route measures 7.2 cm on the map. How long is the real route in kilometres?|7.2*25000/100000|0.18;18;180|Multiply 7.2 cm by 25000 to get 180000 cm.~There are 100000 cm in a kilometre, so the distance is 1.8 km.
maths-ratios-rates|M|Adults and children at a workshop are in the ratio 3:8. There are 44 people altogether. How many are children?|44/11*8|12;24;36|The eleven ratio parts represent 44 people, giving four people per part.~Eight parts are children, so 8 times 4 = 32.
maths-ratios-rates|C|Six workers each make 8 badges an hour. They work for 2.5 hours, but 15 badges are faulty. How many usable badges are made?|6*8*2.5-15|90;115;120|The team makes 48 badges an hour, so in 2.5 hours it makes 120.~Subtract the 15 faulty badges to leave 105 usable ones.
maths-ratios-rates|M|A car uses 7 litres per 100 km. It begins with 35 litres and travels 280 km. How many litres remain?|35-7*280/100|14;19.6;28|For 280 km, fuel used is 2.8 times 7 = 19.6 litres.~Subtract 19.6 from 35 to obtain 15.4 litres remaining.
maths-ratios-rates|M|A painter mixes yellow and white in the ratio 5:3. She has 12 litres of white and enough yellow. How many litres of paint can she make?|12/3*8|20;28;36|Three parts of white equal 12 litres, so one part is four litres.~Eight parts of mixture therefore make 32 litres, including 20 litres of yellow.
maths-ratios-rates|C|On a walk, the first 3 km take 30 minutes and the next 2 km take 40 minutes. What is the average speed in kilometres per hour? Round to six decimals if needed.|5/(70/60)|4;4.5;5|The total distance is 5 km and the total time is 70 minutes, or 7/6 hours.~Divide 5 by 7/6 to get 30/7, about 4.285714 km/h. Averaging the two segment speeds would give the wrong weighting.
maths-ratios-rates|C|Blue and gold beads are in the ratio 4:3. Adding 10 gold beads changes the ratio to 1:1. How many beads were there originally?|10*7|40;60;80|The original excess of blue beads is one ratio part, and equals the ten added gold beads.~One part is ten, so the original seven parts total 70 beads.
maths-ratios-rates|M|A machine packs 84 envelopes in 6 minutes. At the same rate, how many envelopes can it pack in 25 minutes?|84/6*25|294;336;364|The machine packs 14 envelopes per minute.~In 25 minutes it packs 14 times 25 = 350 envelopes.
maths-ratios-rates|C|A shuttle departs every 18 minutes from 9:10 am. The first departure after 10:00 am is how many minutes after 10:00 am?|10+3*18-60|2;8;12|The departures after 9:10 are 9:28, 9:46 and 10:04.~The first after 10:00 is 10:04, four minutes later; 10:00 is not itself a departure.
maths-ratios-rates|M|Four equal jars hold 3 litres altogether. How many such jars are needed to hold 9.75 litres, with none partly filled?|9.75/(3/4)|10;12;14|Each jar holds 3/4 litre.~Dividing 9.75 by 0.75 gives 13 jars exactly.
maths-ratios-rates|C|A 12 km journey takes 50 minutes including a 10-minute stop. What is the moving speed in kilometres per hour?|12/((50-10)/60)|12;14.4;20|The traveller is moving for only 40 minutes, or 2/3 hour.~Twelve divided by 2/3 is 18 km/h. Including the stop would measure a different average.
maths-geometry|E|A rectangle is 9 cm long and 4 cm wide. How many centimetres of edging are needed to go around it once?|2*(9+4)|13;26.5;36|Edging follows the perimeter, which has two lengths and two widths.~Add 9 + 4 + 9 + 4 to get 26 cm, rather than multiplying to get area.
maths-geometry|E|A rectangular box measures 8 cm by 5 cm by 3 cm internally. What is its capacity in cubic centimetres?|8*5*3|16;40;80|Find the base area: 8 times 5 = 40 square centimetres.~Multiply by the 3 cm height to get 120 cubic centimetres.
maths-geometry|M|A rectangular floor is 6 m by 4 m. Square tiles have side length 0.5 m. Ignoring gaps, how many tiles cover the floor?|6*4/(0.5*0.5)|48;72;192|The floor area is 24 square metres; each tile has area 0.25 square metre.~24 divided by 0.25 gives 96 tiles; dividing by the side length would confuse length with area.
maths-geometry|C|An L-shaped garden is made by removing a 3 m by 2 m corner from an 8 m by 5 m rectangle. What is the garden area in square metres?|8*5-3*2|25;30;46|The enclosing rectangle has area 40 square metres.~The removed corner has area 6 square metres, leaving 34 square metres.
maths-geometry|M|Two angles in a triangle are 48 degrees and 67 degrees. What is the third angle in degrees?|180-48-67|55;75;115|Angles in a triangle total 180 degrees.~Subtract 48 + 67 = 115 from 180 to obtain 65 degrees.
maths-geometry|C|A rectangular pond is 10 m by 6 m. A 1 m wide path surrounds it on the outside. What is the area of the path in square metres?|(10+2)*(6+2)-10*6|16;32;48|The outer dimensions are 12 m by 8 m because the path adds a metre on both sides.~Subtract the pond area 60 from the outer area 96 to get 36 square metres of path.
maths-geometry|M|A square and a rectangle both have perimeter 32 cm. The rectangle is 10 cm long. How much larger is the square's area in square centimetres?|(32/4)**2-10*(32/2-10)|2;8;16|The square has side 8 cm and area 64 square centimetres.~The rectangle has width 6 cm and area 60, so the difference is 4 square centimetres.
maths-geometry|C|A cuboid has a square base of side 6 cm and volume 252 cubic centimetres. What is its total surface area in square centimetres?|2*36+4*6*(252/36)|180;216;252|The base area is 36, so the height is 252/36 = 7 cm.~Two bases contribute 72 and four side faces contribute 4 times 6 times 7 = 168, giving 240 square centimetres.
maths-geometry|M|A straight angle is split into three angles in the ratio 2:3:4. How many degrees are in the largest angle?|180/9*4|40;60;90|The nine ratio parts total 180 degrees, so each part is 20 degrees.~The largest angle is four parts, or 80 degrees.
maths-geometry|C|A cube of side 4 cm is painted on all faces and cut into 1 cm cubes. How many small cubes have paint on exactly one face?|6*(4-2)**2|8;16;32|On each face, only the inner 2 by 2 array has exactly one painted face.~There are four such cubes on each of six faces, giving 24; edge and corner cubes have more paint.
maths-geometry|M|A rectangle has area 96 square centimetres and width 8 cm. What is its perimeter in centimetres?|2*(96/8+8)|20;32;48|Divide area by width to obtain the length, 12 cm.~The perimeter is 2 times (12 + 8) = 40 cm.
maths-geometry|C|A right-angled path goes 8 m east, 5 m north, 3 m west and 2 m south. What is the shortest distance back to the start using only east-west and north-south paths, in metres?|(8-3)+(5-2)|6;10;18|The final position is 5 m east and 3 m north of the start.~A shortest route restricted to the two directions covers 5 + 3 = 8 m; a diagonal is not allowed.
maths-geometry|M|A clock's minute hand turns from 2:10 pm to 2:35 pm. Through how many degrees does it turn?|25*6|125;180;210|The minute hand rotates 360 degrees in 60 minutes, or six degrees per minute.~In 25 minutes it turns 150 degrees, regardless of where on the clock it starts.
maths-geometry|C|A 30 cm wire forms a rectangle whose length is twice its width plus 3 cm. What is the rectangle's area in square centimetres?|((30/2-3)/3)*(2*((30/2-3)/3)+3)|36;40;48|Length plus width is 15 cm. With length = 2 widths + 3, three widths total 12, so width is 4 cm.~Length is 11 cm and area is 4 times 11 = 44 square centimetres.
maths-geometry|M|A triangular sign has base 14 cm and perpendicular height 9 cm. What is its area in square centimetres?|14*9/2|23;46;126|A triangle's area is half its base times its perpendicular height.~Half of 14 times 9 is 63 square centimetres; 126 is the enclosing rectangle's area.
maths-geometry|C|A large rectangle consists of three identical squares in one row. Its perimeter is 56 cm. What is its area in square centimetres?|3*(56/8)**2|98;112;196|If each square has side s, the rectangle is 3s by s and has perimeter 8s.~Thus s is 7 cm, and the area is 3 times 7 squared = 147 square centimetres.
maths-algebra|E|A mystery number is multiplied by 4 and then 7 is added, producing 39. What is the number?|(39-7)/4|7;9;11.5|Undo the addition first: 39 minus 7 = 32.~Undo multiplication by dividing 32 by 4, giving 8.
maths-algebra|M|A ticket office sells adult tickets at $12 and child tickets at $7. A family buys 2 adult tickets and some child tickets for $59. How many child tickets did it buy?|(59-2*12)/7|3;4;7|The two adult tickets cost $24, leaving $35 for child tickets.~Each child ticket is $7, so there are five child tickets.
maths-algebra|C|Two consecutive odd numbers have a sum of 88. What is the larger number?|(88-2)/2+2|43;44;47|Write the numbers as x and x + 2. Their sum is 2x + 2 = 88.~The smaller is 43 and the larger is 45; consecutive odd numbers differ by two.
maths-algebra|M|A taxi fare is a $5 starting charge plus $2.40 per kilometre. A ride costs $26.60. How many kilometres was the ride?|(26.6-5)/2.4|8;10;11|Subtract the fixed $5 to leave $21.60 in distance charges.~Divide by $2.40 per kilometre to get 9 km.
maths-algebra|M|Lena is twice as old as Theo. In 6 years their combined ages will be 45. How old is Lena now?|(45-12)/3*2|20;24;30|The two ages gain a combined 12 years, so their current total is 33.~Their current ratio is 2:1, so Lena has two of three parts: 22 years.
maths-algebra|M|A number divided by 3 is 5 more than the number divided by 4. What is the number?|5/(1/3-1/4)|20;36;48|The difference between one third and one quarter is one twelfth.~One twelfth of the number is 5, so the number is 60.
maths-algebra|C|A club hires a room for $84 and pays $6 per participant for materials. It charges $13 per participant. What is the smallest number of participants needed to cover all costs?|84/(13-6)|7;11;14|Each participant contributes $13 minus $6 = $7 towards the room.~Twelve contributions of $7 cover $84 exactly; fewer than twelve leave a shortfall.
maths-algebra|C|A father has 3 times his daughter's age. Eight years ago he had 5 times her age. How old is the daughter now?|(5*8-8)/(5-3)|12;20;24|If the daughter is d now, eight years ago the ages were d - 8 and 3d - 8.~The equation 3d - 8 = 5(d - 8) gives 2d = 32 and d = 16.
maths-algebra|M|The sum of three equally spaced numbers is 72. The smallest is 19. What is the largest?|2*(72/3)-19|24;27;34|For three equally spaced numbers, the middle equals their average, 24.~The gap from 19 to 24 is five, so the largest is 29.
maths-algebra|C|A shop sells pens for $3 and notebooks for $5. Twelve items cost $46. How many notebooks were bought?|(46-12*3)/(5-3)|4;6;7|If all twelve items were pens, they would cost $36.~The extra $10 is $2 for each notebook replacing a pen, so there are five notebooks.
maths-algebra|M|A square number is greater than 60 and less than 90. Its digits add to 13. What is the number?|8**2|72;81;86|The square numbers in the interval are 64 and 81.~Only 64 has digits summing to 13, so it meets both conditions.
maths-algebra|M|Three boxes contain 100 marbles in total. The second has 8 more than the first, and the third has twice the first. How many are in the third box?|(100-8)/4*2|40;44;48|If the first has x, the total is x + (x + 8) + 2x = 4x + 8.~Thus x = 23 and the third box has 46 marbles; the other two boxes have 23 and 31.
maths-algebra|M|A number machine subtracts 9, divides by 4 and gives 7.5. What number entered the machine?|7.5*4+9|21;30;34|Work backwards by multiplying 7.5 by 4 to get 30.~Then restore the subtracted 9 to get 39.
maths-algebra|C|The mean of four test scores is 17. A fifth score raises the mean to 18. What is the fifth score?|5*18-4*17|18;21;24|Four scores total 4 times 17 = 68.~Five scores must total 5 times 18 = 90, so the new score is 22.
maths-algebra|M|A sequence starts at 7 and adds 4 each time. What is its twentieth term?|7+19*4|76;79;87|There are nineteen jumps from the first to the twentieth term.~Add nineteen lots of four to seven to get 83; counting twenty jumps goes one term too far.
maths-algebra|C|A cinema has 18 rows. Each row has 2 more seats than the row before. The first row has 12 seats. How many seats are there altogether?|18*(12+(12+17*2))/2|504;510;540|The last row has 12 + 17 times 2 = 46 seats.~Pair first with last: each pair totals 58. Nine pairs give 522 seats.
maths-directed-numbers|E|The temperature is -4 degrees Celsius at dawn and rises by 11 degrees. What is the new temperature in degrees Celsius?|-4+11|-15;-7;15|From -4, a rise of four degrees reaches zero.~The remaining seven-degree rise reaches 7 degrees Celsius.
maths-directed-numbers|E|A lift starts on level 3, descends 7 levels and then rises 2. What level does it reach?|3-7+2|-6;-4;2|Descending seven from level 3 reaches level -4.~Rising two levels then reaches level -2; count zero as a level on the number line.
maths-directed-numbers|M|A submarine is 35 m below sea level and a drone is 48 m above it. What is the vertical distance between them in metres?|48-(-35)|13;48;73|Treat the positions as -35 m and +48 m.~Their separation crosses sea level: 35 + 48 = 83 m.
maths-directed-numbers|M|A game gives 8 points for a win and subtracts 3 for a loss. Bea wins 5 rounds and loses 7. What is her score?|5*8-7*3|17;21;61|The five wins give 40 points and the seven losses remove 21.~Subtract 21 from 40 to obtain 19 points; losses are not added.
maths-directed-numbers|C|At midnight it is -6 degrees. It rises 2 degrees per hour for 5 hours, then falls 3 degrees per hour for 4 hours. What is the final temperature in degrees Celsius?|-6+2*5-3*4|-2;2;16|The first change is +10, taking the temperature to 4 degrees.~The next change is -12, so the final temperature is -8 degrees Celsius.
maths-directed-numbers|M|A bank balance is -$18. A deposit of $45 arrives, then a $32 bill is paid. What is the final balance in dollars?|-18+45-32|-95;5;59|After the deposit, the balance is -18 + 45 = $27.~Paying $32 takes the balance to -$5.
maths-directed-numbers|C|Numbers -9, -2, 4 and 11 are on a number line. What is the distance between the midpoint of the first pair and the midpoint of the second pair?|(4+11)/2-(-9-2)/2|6;11;15|The first midpoint is (-9 - 2)/2 = -5.5 and the second is (4 + 11)/2 = 7.5.~Their distance is 7.5 minus -5.5 = 13 units.
maths-directed-numbers|M|A hiker begins at an elevation of -12 m and finishes at 31 m. She climbs 58 m in total. How many metres does she descend?|58-(31-(-12))|12;19;27|The net rise is 31 minus -12 = 43 m.~If she climbs 58 m, the excess 58 - 43 = 15 m must be cancelled by descent.
maths-directed-numbers|C|Four temperatures have mean -1 degree. Three of them are -7, -3 and 6 degrees. What is the fourth temperature in degrees Celsius?|4*(-1)-(-7-3+6)|-8;-2;4|The total of all four temperatures must be -4.~The three known values total -4 already, so the missing temperature is 0 degrees.
maths-probability|E|A fair six-sided die is rolled once. How many of its six outcomes are greater than 4?|6-4|1;3;4|The outcomes greater than four are five and six.~There are two favourable outcomes; the question asks for a count rather than the probability 2/6.
maths-probability|M|A bag holds 5 red, 3 blue and 2 white tokens. One token is selected at random. What is the probability that it is not blue? Give a decimal.|(5+2)/(5+3+2)|0.3;0.5;0.8|There are ten equally likely tokens, of which seven are red or white.~The probability of not blue is 7/10 = 0.7, the complement of 0.3.
maths-probability|C|A fair coin and a fair six-sided die are used. What is the probability of a tail and an even number? Give a decimal.|1/2*3/6|0.125;0.5;0.75|The probability of a tail is 1/2 and of an even die result is 3/6.~The independent events both occur with probability (1/2)(3/6) = 1/4 = 0.25.
maths-probability|M|Cards numbered 1 to 20 are shuffled. How many cards show a multiple of 3 or a multiple of 5, counting each card once?|6+4-1|8;10;12|There are six multiples of three and four multiples of five.~The number 15 is in both lists, so subtract one duplicate to get nine cards.
maths-probability|C|Two fair four-sided dice each show numbers 1 to 4. How many of the 16 ordered outcomes have sum 6?|3|2;4;6|List the possible pairs: (2,4), (3,3) and (4,2).~These are three ordered outcomes; (4,2) and (2,4) count separately because the dice are distinguishable.
maths-probability|C|A box contains 4 purple and 2 orange balls. One orange ball is removed without replacing it. A new ball is then drawn randomly. What is the probability of purple on the new draw? Give a decimal.|4/(4+2-1)|0.5;0.666667;0.75|Removing an orange leaves four purple and one orange ball.~Four of the five remaining balls are purple, so the probability is 4/5 = 0.8.
maths-probability|M|A spinner has 8 equal sectors: 3 yellow, 2 green and 3 violet. In 80 spins, how many green results would you expect on average?|80*2/8|10;30;40|Each spin has green probability 2/8 = 1/4.~One quarter of 80 is 20. This is an expectation, not a guarantee about actual spins.
maths-probability|C|A bag contains 3 black and 2 white counters. Two counters are drawn without replacement. What is the probability of one of each colour in either order? Give a decimal.|3/5*2/4+2/5*3/4|0.3;0.4;0.5|Black then white has probability (3/5)(2/4) = 0.3.~White then black also has probability 0.3. The disjoint orders sum to 0.6.
maths-probability|M|Three meal choices and four drink choices are available. One particular meal cannot be paired with one particular drink. How many allowed meal-and-drink pairs exist?|3*4-1|7;10;12|Without restrictions there are 3 times 4 = 12 pairs.~Exactly one pair is forbidden, leaving 11 allowed combinations.
maths-probability|C|A code uses two different digits from 1, 2, 3, 4 and 5. The first digit must be even. How many codes are possible?|2*4|6;10;20|The first digit has two choices, 2 or 4.~After either choice, four different digits remain for the second position. Two times four gives eight codes.
''')

numeric('numeracy', r'''
maths-algebra|E|The scores in a quiz are 6, 8, 8, 9 and 14. What is the median score?|8|9;9.5;14|Put the five scores in order; they are already sorted.~The third score has two scores on either side, so the median is 8, regardless of the high score of 14.
maths-algebra|E|A chart records 12 walkers, 9 cyclists and 15 bus travellers. How many more travel by bus than by bicycle?|15-9|3;9;24|Compare only the bus and bicycle groups.~Subtract nine cyclists from fifteen bus travellers to get a difference of six.
maths-geometry|E|A bottle contains 1.2 litres of water. How many millilitres is this?|1.2*1000|12;120;12000|One litre is 1000 millilitres.~Multiply 1.2 by 1000 to get 1200 millilitres; changing units does not change the amount of water.
maths-algebra|M|Five books have mean mass 320 g. Four weigh 280 g, 310 g, 340 g and 360 g. What is the fifth book's mass in grams?|5*320-(280+310+340+360)|290;300;330|The five books together weigh 1600 g.~The known four weigh 1290 g, so the fifth weighs 310 g.
maths-ratios-rates|M|A 90-minute lesson uses 2/5 of its time for investigation and 20 minutes for discussion. How many minutes remain for independent work?|90*(1-2/5)-20|26;36;54|Investigation uses 36 minutes, leaving 54.~Discussion uses another twenty, leaving 34 minutes for independent work.
maths-geometry|M|A container holds 2.4 litres. A cup holds 150 mL. How many full cups can be poured from a full container?|2400/150|12;15;18|Convert 2.4 litres to 2400 millilitres.~2400 divided by 150 is 16 full cups, with no water left over.
maths-algebra|M|A school's four house scores are 37, 42, 35 and 50. How many points must the lowest-scoring house gain to equal the mean of the other three?|((37+42+50)/3)-35|7;9;15|The lowest score is 35; the other scores total 129 and have mean 43.~The lowest house therefore needs 43 minus 35 = 8 points.
maths-fractions-decimals|M|A board is marked at 0.2 m intervals from 0 to 2.4 m inclusive. How many marks are there?|2.4/0.2+1|11;12;14|There are twelve intervals of 0.2 m in 2.4 m.~Including both endpoints gives thirteen marks, one more than the number of intervals.
maths-geometry|M|A film begins at 6:45 pm and lasts 1 hour 48 minutes. A 12-minute discussion follows. At what minute after 8:00 pm does the discussion end?|45+108+12-120|21;33;57|The film ends at 8:33 pm, since 6:45 plus 1 hour 48 minutes gives that time.~The discussion ends at 8:45, which is 45 minutes after 8:00.
maths-probability|M|A fair spinner has ten equal sectors numbered 1 to 10. What is the probability of landing on a prime number? Give a decimal.|4/10|0.3;0.5;0.6|The prime numbers from one to ten are 2, 3, 5 and 7; one is not prime.~Four of the ten equal sectors are favourable, giving probability 0.4.
maths-algebra|M|The range of five scores is 18. The lowest score is 7 and three other scores are 9, 15 and 20. What is the highest score?|7+18|18;20;27|The range equals highest minus lowest.~Add eighteen to seven to obtain the highest score, 25; the intermediate values do not alter the range.
maths-ratios-rates|M|A 5-pack of markers costs $8. A single marker costs $1.90. How much is saved by buying two packs instead of ten singles, in dollars?|10*1.9-2*8|1.5;2;3.8|Ten singles cost $19 and two packs cost $16.~The saving is $3 for the same ten markers.
maths-percentages|M|A class collects 240 cans in week one. Week two's total is 15% higher. How many cans are collected across both weeks?|240+240*1.15|276;480;504|Fifteen per cent of 240 is 36, so week two brings 276 cans.~Add the first week's 240 to obtain 516 cans overall.
maths-geometry|M|A 1.5 m plank is cut into 4 equal pieces. Three cuts each waste 0.4 cm of wood. How long is each finished piece in centimetres?|(150-3*0.4)/4|36.3;37.4;37.5|The three cuts waste 1.2 cm in all, leaving 148.8 cm of usable wood.~Divide by four to obtain 37.2 cm for each finished piece.
maths-algebra|M|A class has 28 pupils. The mean number of borrowed books is 3.5 per pupil. How many books have been borrowed in total?|28*3.5|84;96;112|Mean equals total divided by the number of pupils.~Multiply 3.5 by 28 to obtain the total of 98 books.
maths-geometry|C|A solid built from 1 cm cubes is 5 cubes long, 4 wide and 3 high. A tunnel one cube wide and one cube high runs through the full 5-cube length. How many cubes remain?|5*4*3-5|45;48;60|The original solid contains 5 times 4 times 3 = 60 cubes.~The tunnel removes five cubes, leaving 55; the tunnel passes through one row only.
maths-percentages|C|A shop's cost for an item is $80. It marks it up by 25%, then gives a 10% discount on the marked price. What is the profit in dollars?|80*1.25*0.9-80|8;12;18|The marked price is $100 and the discounted sale price is $90.~Profit is sale price minus the $80 cost, giving $10; the discount is applied after the markup.
maths-probability|C|A three-digit code uses 2, 4 and 7 exactly once each. How many of the possible codes are greater than 500?|2|1;3;4|To exceed 500, the first digit must be 7; neither 2 nor 4 is large enough.~The two remaining digits can be 24 or 42, giving two codes: 724 and 742.
maths-algebra|C|The mean of 6 numbers is 14. Removing the largest leaves a mean of 12 for the remaining 5. What number was removed?|6*14-5*12|16;22;26|The original six numbers total 84, while the remaining five total 60.~The removed number is the difference, 24.
maths-ratios-rates|C|A boat travels 12 km downstream at 6 km/h and returns 12 km upstream at 4 km/h. What is its average speed for the whole trip in km/h?|24/(12/6+12/4)|4;5;5.2|The downstream leg takes two hours and the upstream leg takes three hours.~The whole trip is 24 km in five hours, giving 4.8 km/h, rather than the unweighted mean of the speeds.
maths-geometry|C|A square sheet of side 16 cm is folded in half twice along perpendicular centre lines. A 2 cm square is cut from the corner where both folds meet. How many square centimetres remain after unfolding?|16*16-4*2*2|224;244;252|The folded sheet has four layers, so the corner cut removes four 2 by 2 squares.~The original area is 256 and the removed area is 16, leaving 240 square centimetres.
''')

numeric('numerical_reasoning', r'''
nr-number-series|E|The numbers 6, 11, 16, 21 increase by an equal amount. What is the sixth number?|6+5*5|26;30;36|Each increase is five, so the fifth number is 26.~The question asks for the sixth, which is 31 after one more increase.
nr-number-series|E|A shrinking pattern is 96, 48, 24, 12. Each term is half the previous term. What comes next?|12/2|3;8;10|Check that halving connects each adjacent pair.~Half of twelve is six; subtracting a fixed amount would not match all the earlier changes.
nr-number-series|M|A series is 4, 9, 19, 39, 79. Each step doubles the previous term and adds the same whole number. What is the next term?|79*2+1|158;160;169|Twice four plus one is nine, and the same extra one works for every displayed step.~Twice 79 plus one is 159.
nr-number-series|M|The gaps in 2, 7, 14, 23, 34 increase by 2 each time. What is the next term?|34+13|45;46;49|The gaps are 5, 7, 9 and 11.~The next gap is 13, so add it to 34 to obtain 47.
nr-number-series|C|In 3, 12, 10, 40, 38, 152, the operations alternate between multiplying by 4 and subtracting 2. What is the eighth term?|(152-2)*4|148;150;608|The seventh term follows a subtraction: 152 minus 2 = 150.~The eighth follows multiplication: 150 times 4 = 600. Applying only the next operation stops one term too soon.
nr-number-series|M|Two interleaved sequences form 2, 30, 5, 26, 8, 22, 11, ?. What replaces the question mark?|22-4|14;16;20|The odd positions rise 2, 5, 8, 11 by three.~The even positions fall 30, 26, 22 by four, so the missing even term is 18.
nr-number-series|C|The sequence 2, 5, 11, 23, 47 follows a rule. Its gaps double each time. What is the difference between its next two terms?|(47*2+1)*2+1-(47*2+1)|48;95;192|The gaps are 3, 6, 12 and 24; the next gap is 48, giving a next term of 95.~The gap after that is 96, which is the requested difference between the next two terms.
nr-number-series|M|Each new number in 4, 7, 11, 18, 29 is the sum of the previous two. What is the next number?|18+29|40;44;58|Check 4 + 7 = 11 and 7 + 11 = 18, then 11 + 18 = 29.~The next term is 18 + 29 = 47; doubling 29 would ignore the two-term rule.
nr-number-series|C|A sequence begins 2, 6, 24, 120. The multipliers are consecutive integers beginning with 3. What is the sixth term?|120*6*7|720;2520;5760|The multipliers used are 3, 4 and 5.~The fifth term is 120 times 6 = 720 and the sixth is 720 times 7 = 5040.
nr-number-series|E|Read the pattern 81, 72, 63, 54. Nine is subtracted each time. What number appears after 54?|54-9|36;44;46|The given differences are all minus nine.~54 minus 9 gives 45; 36 is the following term.
nr-number-series|M|The series 1, 4, 10, 19, 31 has gaps increasing by 3. What comes next?|31+15|43;45;49|The successive gaps are 3, 6, 9 and 12.~The next gap is 15, making the next term 46.
nr-number-series|C|A row lists 5, 8, 14, 23, 35. The gap grows by 3 each time. What is the eighth entry?|35+15+18+21|68;83;92|The gaps are 3, 6, 9, 12, then 15, 18 and 21.~Starting from the fifth entry 35, add those three gaps to reach the eighth entry, 89.
nr-number-series|M|In 64, 32, 16, 8, 4, positions are counted from the left starting at 1. What is the sum of positions 6 and 7?|2+1|1.5;2;4|The pattern halves each term, so positions six and seven contain 2 and 1.~Their sum is 3, rather than their product 2.
nr-number-series|C|A sequence begins 1, 3, 8, 19, 42. To get a new term, double the old term and add 1, then 2, then 3, then 4. What is the next term?|42*2+5|84;88;90|The added numbers rise by one each time: 1, 2, 3 and 4.~The next step doubles 42 and adds 5, giving 89.
nr-number-series|M|The terms are squares of consecutive integers, each reduced by 2: 7, 14, 23, 34. What is the next term?|7**2-2|45;48;49|Adding two gives 9, 16, 25 and 36, the squares of 3 through 6.~Next use 7 squared minus 2, obtaining 47.
nr-number-series|C|A pattern alternates addition and multiplication: 3, 7, 14, 18, 36, 40. The same addition and multiplication are reused. What is the ninth term?|((40*2)+4)*2|84;160;172|The alternating rules are add four, then multiply by two.~The next three terms after 40 are 80, 84 and 168, so the ninth is 168.
nr-number-series|M|The first six positive multiples of 7 are written in reverse order. What is the fourth number in this reversed list?|7*3|14;28;35|The reversed list is 42, 35, 28, 21, 14, 7.~The fourth number is 21; the fourth multiple in the ordinary order would be 28.
nr-number-series|C|Differences in a sequence are consecutive square numbers: 2, 3, 7, 16, 32. What is the seventh term?|32+25+36|57;68;96|The gaps are 1, 4, 9 and 16, so the next gaps are 25 and 36.~The sixth term is 57 and the seventh is 93.
nr-number-series|M|A pattern has three-term blocks: 2, 4, 8; 3, 6, 12; 4, 8, 16. Each block doubles twice. What is the last number of the next block?|5*4|10;18;24|The starting numbers rise from 2 to 3 to 4, so the next block starts at 5.~Doubling twice gives 5, 10, 20, with final number 20.
nr-number-series|C|A series decreases by successive prime numbers: 50, 48, 45, 40, 33. Using primes in order from 2, what is the next term?|33-11|20;23;26|The subtractions are 2, 3, 5 and 7, the first four primes.~The next prime is 11, giving 33 minus 11 = 22. Nine is not prime.
nr-number-series|M|The list 3, 6, 5, 10, 9, 18 alternates doubling and subtracting 1. What number follows 18?|18-1|16;19;36|The moves are times two, minus one, repeated.~After 9 is doubled to 18, subtract one to obtain 17.
nr-number-series|C|The list 9, 14, 12, 17, 15, 20 repeats changes of +5 and -2. What is the sum of its seventh and eighth terms?|(20-2)+(20-2+5)|36;39;43|After 20, the seventh term is 18 and the eighth is 23.~Their sum is 41; the alternating changes must both be applied before adding.
nr-number-series|M|A sequence uses successive cubes plus 1: 2, 9, 28, 65. What comes next?|5**3+1|101;125;216|Subtracting one gives 1, 8, 27 and 64, which are cubes of 1 through 4.~The next cube is 125; restoring the extra one gives 126.
nr-number-series|C|In the sequence 7, 10, 16, 28, 52, each gap is twice the previous gap. What is the seventh term?|52+48+96|100;148;200|The gaps are 3, 6, 12 and 24, followed by 48 and 96.~The sixth term is 100 and the seventh is 196.
nr-number-series|E|A number line starts at 17 and marks every third integer after that. What is the fifth marked number, counting 17 first?|17+4*3|26;31;32|There are four equal jumps between the first and fifth marks.~Add four threes to seventeen to get 29.
nr-number-series|M|The repeating unit is 4, 1, 7, 9, 2. What number occupies position 38, counting the first 4 as position 1?|7|1;2;9|Divide 38 by the cycle length five: the remainder is three.~Position 38 is the third position in a cycle, containing 7.
nr-number-series|C|A row alternates two patterns: 1, 3, 4, 6, 9, 12, 16, 24, ?. Odd positions are consecutive squares and even positions double. What is missing?|5**2|20;32;48|Odd positions read 1, 4, 9, 16, which are the squares of 1 through 4.~The ninth position is odd, so it contains 5 squared = 25, not the next doubled even-position term.
nr-number-series|M|Starting with 100, subtract 4, then 8, then 12, then 16. What value is reached after all four subtractions?|100-4-8-12-16|56;64;84|The four subtractions total 4 + 8 + 12 + 16 = 40.~Subtract 40 from 100 to get 60; stopping before the last subtraction gives 76.
nr-number-series|C|A pattern begins 2, 3, 6, 11, 18. Its successive gaps are odd numbers from 1. What is the sum of the sixth and seventh terms?|(18+9)+(18+9+11)|47;54;76|The gaps used are 1, 3, 5 and 7, so the next terms are 27 and 38.~Their sum is 65. Both new terms are required rather than just the next gap.
nr-number-series|M|In a sequence of fractions, the numerators are 1, 3, 5, 7 and denominators are all 8. What is the decimal value of the next term?|9/8|0.875;1;1.25|Numerators increase by two, so the next fraction is 9/8.~Nine divided by eight is 1.125; a numerator larger than the denominator gives a value above one.
nr-number-series|C|The series 2, 4, 7, 12, 20, 33 has gaps 2, 3, 5, 8, 13. Each gap after the first two sums the previous two gaps. What is the next term?|33+8+13|46;53;56|The next gap is 8 + 13 = 21.~Add this to 33 to obtain 54; the gap follows the stated recurrence, not a doubling rule.
nr-number-series|M|A staircase uses 5 blocks on its first step, 8 on its second, 11 on its third and 14 on its fourth. If the pattern continues, how many blocks are in the seventh step?|5+6*3|20;24;26|The number of blocks rises by three per step.~From step one to step seven there are six increases, so 5 + 18 = 23 blocks.
nr-number-series|C|A sequence's first term is 4. Each later term equals three times the previous term minus 2. What is its fourth term?|((4*3-2)*3-2)*3-2|76;80;84|The second term is 10 and the third is 28.~The fourth is three times 28 minus 2 = 82; the subtraction occurs at every step.
nr-number-series|M|Pairs in a list are (2, 7), (4, 13), (6, 19), (8, ?). The second number is three times the first plus one. What is missing?|8*3+1|21;24;27|Check the relationship: 2 times 3 plus 1 is 7, and it also gives 13 and 19.~For 8, calculate 24 + 1 = 25.
nr-number-series|C|A row gives 1, 2, 6, 15, 31. The gaps are 1 squared, 2 squared, 3 squared and 4 squared. What number occurs two places after 31?|31+25+36|56;67;96|The next gap is 5 squared = 25, giving 56.~The following gap is 6 squared = 36, so the requested term is 92.
nr-number-series|M|The pattern 5, 15, 45, 135 multiplies by 3 each time. What is the ratio of the fifth term to the third term?|3**2|3;6;27|Moving from the third to fifth term takes two multiplications by three.~The ratio is 3 times 3 = 9; there is no need to compute both large terms separately.
nr-number-series|C|A cycle of changes is +2, +5, -3. Starting at 10, what number is reached after 8 changes?|10+2*(2+5-3)+2+5|21;24;28|Each full three-change cycle adds four. Six changes make two cycles, taking 10 to 18.~The seventh and eighth changes add two and five, reaching 25.
nr-number-series|M|The sequence 90, 85, 75, 60, 40 subtracts consecutive multiples of 5. What comes next?|40-25|10;20;25|The subtractions are 5, 10, 15 and 20.~The next is 25, leaving 15.
nr-number-series|C|A sequence starts with 6, 10. Each later term is the sum of the previous two minus 1. What is the sixth term?|((6+10-1)+(10+(6+10-1)-1)-1)+(10+(6+10-1)-1)-1|52;60;64|The next terms are 15, 24 and 38, found by summing the previous two then subtracting one.~The sixth term is 24 + 38 - 1 = 61.
nr-number-series|M|A pattern writes 2, 6, 12, 20, 30 as products of consecutive integers: 1 times 2, 2 times 3, and so on. What is the eighth term?|8*9|56;64;90|The term in position n is n times (n + 1).~The eighth term is 8 times 9 = 72, rather than the eighth square 64.
''')

numeric('numerical_reasoning', r'''
nr-arithmetical-reasoning|E|At a table, every child shakes hands once with the adult host. There are 9 children and no other handshakes. How many handshakes occur?|9|8;10;18|Each of the nine children contributes one handshake with the host.~These are nine different handshakes; counting both participants would incorrectly double the result.
nr-arithmetical-reasoning|M|A row of 18 fence panels has one post between adjacent panels and one post at each end. How many posts are needed?|18+1|17;18;36|Seventeen posts lie between eighteen panels.~Adding the two end posts gives nineteen; sharing a post between panels avoids needing two for every panel.
nr-arithmetical-reasoning|C|A ribbon is cut into equal pieces using 7 straight cuts, cutting only one unstacked piece at a time. How many more cuts are needed to make 15 pieces in total?|(15-1)-7|6;8;15|Starting with one piece, each cut adds exactly one piece. Fifteen pieces therefore need fourteen cuts.~Seven cuts have already been made, leaving seven more.
nr-arithmetical-reasoning|M|A staircase has 24 steps. Nia climbs 3 steps with each stride and descends 2 steps with each stride. How many strides does a full up-and-down trip take?|24/3+24/2|10;16;24|Climbing takes eight strides and descending takes twelve.~Add the two different stride counts to obtain twenty for the round trip.
nr-arithmetical-reasoning|C|A hall has tables seating 6. Joining two tables along an end removes 2 available seats; every join does the same. How many seats are available when 9 tables form one straight line?|9*6-8*2|36;40;52|Nine separate tables provide 54 seats.~A line of nine tables has eight joins, removing sixteen seats, so 38 remain.
nr-arithmetical-reasoning|M|Six people each send one card to each of the other five people. How many cards are sent?|6*5|15;25;36|Every one of six senders writes five cards.~Six times five is thirty; unlike a handshake, a card from A to B differs from a card from B to A.
nr-arithmetical-reasoning|C|At a reunion each of 8 people shakes hands once with each other person. How many handshakes occur?|8*7/2|21;32;56|Counting seven partners for each person gives 56 person-pairs.~Each handshake is counted twice that way, so divide by two to get 28.
nr-arithmetical-reasoning|M|A queue has 26 people. Ravi is ninth from the front. What is his position from the back?|26-9+1|16;17;19|There are seventeen people behind Ravi.~He is therefore eighteenth from the back; include Ravi himself when numbering positions.
nr-arithmetical-reasoning|C|A printer numbers pages 1 to 35. How many individual digits does it print for those page numbers?|9+(35-9)*2|35;60;70|Pages one to nine use nine digits.~The other 26 pages use two digits each, so the total is 9 + 52 = 61 digits.
nr-arithmetical-reasoning|M|A clock chimes once at 1 o'clock, twice at 2 o'clock and so on up to 6 o'clock. How many chimes sound from 1 through 6 inclusive?|1+2+3+4+5+6|15;18;24|Add the chimes for each hour: 1 + 2 + 3 + 4 + 5 + 6.~The sum is 21, including the single chime at one and six chimes at six.
nr-arithmetical-reasoning|C|A snail climbs 5 m each day and slips 2 m each night. It starts at the bottom of a 17 m pole. On which day does it first reach the top?|5|4;6;7|After four full day-night cycles the snail is at 12 m.~On day five it climbs to 17 m and finishes before another slip. Dividing by the net daily gain overlooks the final day.
nr-arithmetical-reasoning|M|Three children share 42 tokens. Each receives the same number, then each gives 2 tokens to a class jar. How many tokens do the children keep altogether?|42-3*2|12;36.5;40|Each child first receives fourteen tokens and then keeps twelve.~Three lots of twelve total 36, equivalent to subtracting six donated tokens from forty-two.
nr-arithmetical-reasoning|C|An event uses ticket numbers 125 through 180 inclusive. Each ticket has a unique number. How many tickets are there?|180-125+1|54;55;57|The difference between the endpoint numbers is 55.~Both endpoints count, so the number of tickets is 56.
nr-arithmetical-reasoning|M|A robot repeats forward 4 squares, then backward 1 square. After 6 complete repetitions, how far forward is it from the start in squares?|6*(4-1)|15;24;30|A complete repetition gains 4 - 1 = 3 squares.~Six repetitions gain 18 squares, rather than the 24 squares travelled forward alone.
nr-arithmetical-reasoning|C|A bell rings every 12 minutes and another every 18 minutes. They ring together at noon. How many minutes later will they next ring together?|36|24;30;72|The next common ringing time is the least common multiple of 12 and 18.~Their multiples first coincide at 36, so the next joint ringing is at 12:36 pm.
nr-arithmetical-reasoning|M|Four friends split a $46 bill equally after using a $6 voucher. How much does each pay in dollars?|(46-6)/4|8.5;11.5;13|The voucher reduces the shared bill to $40.~Dividing equally among four people gives $10 each, rather than dividing the original price.
nr-arithmetical-reasoning|C|A box has 24 socks: 8 each in three colours. Drawing without looking, how many socks guarantee at least one matching-colour pair?|4|2;3;9|The first three socks might all have different colours.~The fourth must repeat one of the three colours, guaranteeing a pair. Two would only make a pair possible.
nr-arithmetical-reasoning|M|On a circular track, markers are equally spaced at 15 m intervals. There are 12 markers. What is the track length in metres?|12*15|165;195;210|A circle has an interval from the last marker back to the first.~There are twelve intervals rather than eleven, so the length is 180 m.
nr-arithmetical-reasoning|C|A team must move 29 boxes. A cart carries at most 6 boxes per trip. Every trip leaves full unless fewer boxes remain. How many boxes are on the last trip?|29%6|4;6;5.5|Four full trips move 24 boxes.~The remaining 29 - 24 = 5 boxes are carried on the fifth and last trip.
nr-arithmetical-reasoning|M|A book has 96 pages. Kai reads 12 pages daily for 5 days, then 9 pages daily. How many more days are needed?| (96-12*5)/9|3;5;6|The first five days cover 60 pages, leaving 36.~At nine pages per day, the remaining reading takes four days.
nr-arithmetical-reasoning|C|A line of trees runs 0 m, 8 m, 16 m and so on to 96 m. Every third tree, counting the first as tree 1, is an elm. How many elms are there?|4|3;5;6|There are thirteen trees, including both endpoints.~The elm positions are 3, 6, 9 and 12, giving four elms.
nr-arithmetical-reasoning|M|A machine needs 3 minutes to stamp its first coin, then produces a coin every 2 minutes. How many minutes after starting is its tenth coin ready?|3+9*2|18;20;23|The first coin is ready at three minutes.~Nine further intervals of two minutes lead to the tenth coin at 21 minutes.
nr-arithmetical-reasoning|C|A digital counter starts at 200 and drops by 7 after each signal. How many signals have occurred when it first shows a number below 150?|8|6;7;9|Seven signals reduce the counter by 49 to 151, which is still above 150.~An eighth signal takes it to 144, the first value below the threshold.
nr-arithmetical-reasoning|M|A tile pattern uses 4 tiles for the first shape and adds 3 tiles for every extra shape. How many tiles are needed for 12 shapes in the joined pattern?|4+11*3|33;36;48|The first shape uses four tiles; only eleven additional shapes are added.~Eleven groups of three add 33, making 37 tiles altogether.
nr-arithmetical-reasoning|C|A jar holds $2 and 50-cent coins. There are 14 coins worth $19 altogether. How many are $2 coins?|(19-14*0.5)/(2-0.5)|6;9;12|Fourteen 50-cent coins would be worth $7.~Each $2 coin adds $1.50 above that baseline; the extra $12 requires eight $2 coins.
nr-logic-deduction-numbers|E|A secret whole number is greater than 20 and less than 30. It is divisible by 4 and by 6. What is it?|24|22;26;28|The multiples of four in the interval are 24 and 28.~Only 24 is also divisible by six, so it meets both clues.
nr-logic-deduction-numbers|M|Three consecutive integers total 87. What is their smallest value?|87/3-1|27;29;30|The middle of three consecutive integers equals their average, 29.~The smallest is one less, 28; the numbers 28, 29 and 30 sum to 87.
nr-logic-deduction-numbers|C|A two-digit number is four times the sum of its digits. Its tens digit is 3. What is the number?|36|32;34;39|Write the number as 30 + u. The clue gives 30 + u = 4(3 + u).~Thus 18 = 3u and u = 6, so the number is 36.
nr-logic-deduction-numbers|M|A whole number leaves remainder 2 when divided by 5. It lies between 30 and 40 and is even. What is the number?|32|34;37;42|Numbers in the interval with remainder two are 32 and 37.~Only 32 is even, so it satisfies both the interval and remainder conditions.
nr-logic-deduction-numbers|C|An integer from 1 to 50 is divisible by 6, but not by 4. Its digits total 9. What is it?|18|24;30;36|The multiples of six with digit sum nine are 18 and 36.~Thirty-six is divisible by four, leaving 18 as the sole value satisfying every condition.
nr-logic-deduction-numbers|M|A number has hundreds digit 4 and units digit 7. Its digits sum to 16. What is its tens digit?|16-4-7|4;6;9|The known digits total eleven.~The remaining digit must be 16 minus 11 = 5, making the number 457.
nr-logic-deduction-numbers|C|Ages of three siblings are consecutive even numbers. Their sum is 42. What will the oldest sibling's age be in 5 years?|42/3+2+5|16;19;23|The middle age is 42/3 = 14, so the ages are 12, 14 and 16.~The oldest will be 16 + 5 = 21 in five years.
nr-logic-deduction-numbers|M|A secret number is a factor of 72 and a multiple of 8. It is greater than 10 but less than 30. What is it?|24|16;18;28|Multiples of eight in the interval are 16 and 24.~Only 24 divides 72 exactly, giving a single match.
nr-logic-deduction-numbers|C|Two whole numbers have product 84 and differ by 5. What is their sum?|7+12|17;21;25|Factor pairs of 84 include (1,84), (2,42), (3,28), (4,21), (6,14) and (7,12).~Only 7 and 12 differ by five; their sum is 19.
nr-logic-deduction-numbers|M|A four-digit lock code has digits that increase by 2 from left to right. Its first digit is 1. What is the sum of all four digits?|1+3+5+7|12;14;18|Starting at one and increasing by two gives digits 1, 3, 5 and 7.~Their sum is 16; the code itself would be 1357.
nr-logic-deduction-numbers|C|A bag contains only red and blue beads. There are twice as many red as blue. Removing 6 red beads leaves equal numbers of both colours. How many beads were there originally?|6*3|12;21;24|If blue beads number b, red beads number 2b. Equality after removal gives 2b - 6 = b.~Thus b = 6 and the original total is 12 + 6 = 18.
nr-logic-deduction-numbers|M|A number rounded to the nearest ten is 70. Its units digit is 3. What is the number?|73|63;67;83|Numbers rounding to seventy lie from 65 through 74.~Only 73 in that interval has units digit three.
nr-logic-deduction-numbers|C|Three balance clues are A + B = 17, B + C = 23 and A + C = 20. What is C?|(23+20-17)/2|10;12;16|Adding the last two sums and subtracting the first cancels A and B, leaving 2C.~Thus 2C = 23 + 20 - 17 = 26, so C = 13.
nr-logic-deduction-numbers|M|A number is odd, greater than 40 and less than 50. It is not prime and is divisible by 3. What is it?|45|43;47;49|The odd numbers in the interval are 41, 43, 45, 47 and 49.~Only 45 is divisible by three, and it is composite, so it meets all clues.
nr-logic-deduction-numbers|C|Four consecutive whole numbers total 74. What is the product of the two middle numbers?|18*19|306;324;380|The average is 18.5, putting the four numbers at 17, 18, 19 and 20.~The middle pair is 18 and 19; their product is 342.
nr-logic-deduction-numbers|M|The digits 2, 5 and 8 are each used once to make the largest possible even three-digit number. What is that number?|852|825;528;582|An even number must end with 2 or 8.~Using 2 last allows the largest hundreds digit 8 and then 5, giving 852, larger than any arrangement ending in 8.
nr-logic-deduction-numbers|C|A number from 100 to 150 has digit sum 9 and is divisible by 5. What is it?|135|105;120;145|Divisibility by five requires a last digit of zero or five.~Checking the range with digit sum nine leaves 135; numbers ending in zero in the range have digit sums at most five.
nr-logic-deduction-numbers|M|A square number lies between 30 and 60. Dividing it by 7 gives a whole number. What is the square number?|49|35;36;56|The squares in the interval are 36 and 49.~Only 49 is divisible by seven, so the required number is 49.
nr-logic-deduction-numbers|C|A store has between 40 and 60 eggs. Packing them in groups of 6 leaves 3 eggs, while groups of 5 leave none. How many eggs are there?|45|50;51;55|The multiples of five strictly in the interval are 45, 50 and 55.~Only 45 leaves remainder three on division by six: 45 = 7 times 6 + 3.
nr-logic-deduction-numbers|M|The sum of two numbers is 36 and one is 8 greater than the other. What is the smaller number?|(36-8)/2|12;16;22|Remove the extra eight from the total to obtain two equal smaller numbers totalling 28.~Divide by two to get 14; the larger number is 22.
nr-logic-deduction-numbers|C|A three-digit number is a multiple of 9. Its hundreds and units digits are 6 and 4. What is its tens digit?|8|2;4;6|A multiple of nine has a digit sum divisible by nine.~The known digits total ten, so the tens digit must add eight to reach eighteen. The number is 684.
nr-logic-deduction-numbers|M|A shelf has fewer than 40 and more than 20 books. Grouping them in fours leaves 1 book. Grouping them in sevens leaves none. How many books are there?|21|25;28;35|The multiples of seven in the range are 21, 28 and 35.~Only 21 has remainder one when divided by four, so it satisfies both grouping clues.
nr-logic-deduction-numbers|C|A two-digit number's tens digit is twice its units digit. The number is 27 greater than its reverse. What is the number?|63|42;64;84|If the units digit is u, the tens digit is 2u and the reversal difference is 9u.~Thus 9u = 27, so u = 3, tens digit 6, and the number is 63.
nr-logic-deduction-numbers|M|Three different positive integers have sum 14. The smallest is 2 and the largest is twice the middle one. What is the largest?|8|6;7;10|If the middle is m, then 2 + m + 2m = 14.~Thus m = 4 and the largest is 8; the three integers 2, 4 and 8 meet all conditions.
nr-logic-deduction-numbers|C|A box number is between 70 and 100, is divisible by 8 and has a units digit no larger than its tens digit. Its digits sum to 16. What is it?|88|72;80;96|The multiples of eight in the interval are 72, 80, 88 and 96.~Only 88 has digit sum sixteen; its equal digits also satisfy the condition that the units digit is no larger than the tens digit.
nr-number-matrices|E|In each row, the third entry is the sum of the first two: (4, 9, 13), (7, 8, 15), (12, 6, ?). Find the missing entry.|12+6|6;16;72|The example rows confirm addition: 4 + 9 = 13 and 7 + 8 = 15.~Use the same stated rule in the final row: 12 + 6 = 18.
nr-number-matrices|M|For the triples (3, 5, 16) and (6, 4, 25), the last number is one more than the product of the first two. What finishes (7, 8, ?)?|7*8+1|15;55;56|The rule gives 3 times 5 plus 1 = 16 and 6 times 4 plus 1 = 25.~It gives 7 times 8 plus 1 = 57 in the final row.
nr-number-matrices|M|A grid uses rows (2, 5, 21), (4, 7, 33), (6, 9, ?). The last entry is the square of the second minus the square of the first. What is missing?|9**2-6**2|15;27;117|The rule fits 25 - 4 = 21 and 49 - 16 = 33.~The final result is 81 - 36 = 45, not the square of the difference.
nr-number-matrices|M|A table shows input pairs and their absolute difference: (18, 7, 11), (4, 15, 11), (23, 9, ?). What is the final value?|23-9|12;14.5;32|The absolute difference is the non-negative distance between the input values.~For 23 and 9, subtract the smaller from the larger to obtain 14.
nr-number-matrices|M|Read these rows as first value, second value, output: (3, 2, 11), (5, 4, 29), (7, 6, ?). Output equals first value squared plus second value. What is missing?|7**2+6|43;49;85|Check 3 squared plus 2 = 11 and 5 squared plus 4 = 29.~Seven squared plus six is 55. Squaring the sum instead would apply a different rule.
nr-number-matrices|M|Across every row of a grid, the middle number is the mean of the outer numbers. The rows are (8, 13, 18), (6, 15, 24), (14, ?, 36). Find the missing middle.|(14+36)/2|22;24;26|The mean of two numbers is their sum divided by two.~The outer values sum to fifty, so the missing middle number is 25.
nr-number-matrices|C|In a three-row array, each column totals 40. Two rows are (9, 12, 15) and (14, 8, 6). What is the sum of all entries in the third row?|3*40-(9+12+15+14+8+6)|36;40;60|The whole grid totals three columns times forty = 120.~The two known rows total 64, so the third row totals 56.
nr-number-matrices|M|Each row is a number, its double and its triple. Two rows are (4, 8, 12) and (7, 14, 21). A third row has middle entry 18. What is its last entry?|18/2*3|24;30;36|The middle entry is twice the first, so the first entry is nine.~The last entry is three times nine = 27, which is also 1.5 times the middle entry.
nr-number-matrices|M|Each triple has output equal to the first number times the sum of the first and second: (2, 5, 14), (3, 4, 21), (6, 7, ?). What is missing?|6*(6+7)|42;49;91|The examples give 2 times 7 = 14 and 3 times 7 = 21.~For the final row, 6 times (6 + 7) gives 78. Add inside the bracket first.
nr-number-matrices|M|A grid has row totals 18, 21 and 24. In its third row the first two entries are 5 and 8. What is the third entry?|24-5-8|8;10;13|The third row must total 24, irrespective of the earlier row totals.~Its known entries total thirteen, leaving eleven for the missing entry.
nr-number-matrices|C|A 2 by 2 grid contains top row (3, 8) and bottom row (5, ?). The products of the two diagonals are equal. What is the missing number?|8*5/3|10;12;15|One diagonal has product 8 times 5 = 40.~The other is three times the missing value, so the missing value is 40/3, or 13.333333 to six decimals.
nr-number-matrices|M|A chart changes each number to three less than half of it: 20 becomes 7 and 34 becomes 14. What does 50 become?|50/2-3|20;23.5;28|The rule halves first, then subtracts three, as the two examples show.~Half of fifty is twenty-five; subtracting three gives twenty-two.
nr-number-matrices|C|Rows (2, 3, 13), (4, 1, 17), (5, 2, ?) use the sum of the squares of the first two entries. What replaces the question mark?|5**2+2**2|14;27;49|Two squared plus three squared is thirteen, and four squared plus one squared is seventeen.~For five and two, add twenty-five and four to get twenty-nine.
nr-number-matrices|M|A two-column table pairs each number with its complement to 100: (27, 73), (46, 54), (?, 38). What is the missing number?|100-38|52;58;68|Each pair adds to one hundred.~The partner for thirty-eight is sixty-two, since 62 + 38 = 100.
nr-number-matrices|C|Each row lists two inputs and their product minus their sum: (3, 7, 11), (4, 6, 14), (5, 9, ?). What is missing?|5*9-(5+9)|26;35;45|The first row gives 21 - 10 = 11 and the second gives 24 - 10 = 14.~In the last row compute 45 - 14 = 31, subtracting both input values.
nr-number-matrices|M|In a three-cell row, the second cell is 4 more than the first and the third is twice the second. If the third cell is 30, what is the first cell?|30/2-4|7;13;19|Work backwards: the second cell is half of thirty, which is fifteen.~The first is four less than fifteen, giving eleven.
nr-number-matrices|C|The rows (5, 2, 21) and (7, 3, 40) use the rule (first plus second) times (first minus second). What is the output for (9, 4)?|(9+4)*(9-4)|25;45;169|The examples give 7 times 3 = 21 and 10 times 4 = 40.~For nine and four, multiply thirteen by five to obtain sixty-five.
nr-number-matrices|M|Each cell in the bottom row is the cell above it plus the same constant. The top row is (4, 11, 19), the bottom row is (10, 17, ?). Find the missing value.|19+(10-4)|23;24;30|The constant is six: 10 - 4 and 17 - 11 both equal six.~Add six to nineteen to get twenty-five.
nr-number-matrices|M|Three rows have equal totals: (12, 7, 11), (8, 15, 7), (9, x, 6). What is twice x?|2*(30-9-6)|15;24;36|Each complete row totals thirty.~The third row needs x = 30 - 9 - 6 = 15, so twice x is thirty.
nr-number-matrices|M|The outer entries in each row add to twice the middle: (3, 8, 13), (7, 10, 13), (11, 15, ?). What is missing?|2*15-11|15;18;26|Twice fifteen is thirty, the required total of the outer entries.~Subtract the first entry eleven to find the last entry nineteen.
nr-number-matrices|C|A grid has top row (2, 4, 6) and middle row (3, 5, 7). Each bottom entry is the product of the two cells above it plus their difference, larger minus smaller. What is the sum of the bottom row?|2*3+1+4*5+1+6*7+1|68;70;74|The bottom entries are 2 times 3 plus 1 = 7, 4 times 5 plus 1 = 21, and 6 times 7 plus 1 = 43.~Their sum is 71; apply the extra difference in every column.
nr-number-matrices|M|A row transformation takes (a, b) to (b, a + b). Starting with (4, 9), what is the second entry after two transformations?|9+(4+9)|17;26;31|The first transformation gives (9, 13).~The second gives (13, 22), so the requested second entry is twenty-two.
nr-number-matrices|C|In a number triangle, each upper cell is the sum of the two cells immediately below. The base is (4, x, 7), and the top is 25. What is x?|(25-4-7)/2|6;8;14|The middle row is 4 + x and x + 7.~The top is therefore 11 + 2x = 25; solve 2x = 14 to get x = 7.
nr-number-matrices|M|A table maps (first, second) to their average plus 4. For instance (6, 10) maps to 12. What does (13, 19) map to?|(13+19)/2+4|16;18;24|The average of thirteen and nineteen is sixteen.~Adding four gives twenty; adding before dividing would produce a different result.
nr-number-matrices|C|A square array has top row (6, 14) and bottom row (9, x). The sum of the top row is five less than the bottom-row sum. What is x?|6+14+5-9|6;11;14|The top row totals twenty, so the bottom row must total twenty-five.~Nine plus x is twenty-five, giving x = 16. The bottom sum is the greater one.
''')

verbal(r'''
vr-synonyms-antonyms|E|The path was narrow, so the walkers continued in single file. Which word best replaces narrow here?|slender;crooked;lengthy;crowded|Walking single file suggests little width.~Slender is the closest width word; crooked concerns direction and crowded concerns how many people are present.
vr-synonyms-antonyms|E|When the rain stopped, the children resumed their game. What does resumed mean?|started again;finished early;changed entirely;watched quietly|The rain interrupted the game and the children continued it afterwards.~Started again preserves that meaning; finishing or changing it does not.
vr-synonyms-antonyms|E|The caretaker inspected the gate before allowing the crowd through. Inspected most nearly means what?|examined;replaced;unlocked;decorated|Inspection means looking carefully to check a condition.~Unlocking might happen later, but the sentence does not say it is the inspection itself.
vr-synonyms-antonyms|E|Hana was reluctant to lend her new sketchbook because its pages tore easily. Which word describes reluctant?|unwilling;eager;unable;forgetful|The concern about torn pages explains hesitation about lending.~Unwilling matches that attitude; unable would mean she could not lend it at all.
vr-synonyms-antonyms|E|A temporary bridge carried pedestrians while the old bridge was repaired. Temporary means what?|not permanent;unsafe by design;very narrow;recently damaged|The bridge serves during a limited period of repair.~Not permanent describes its intended duration; neither safety nor width follows from the word.
vr-synonyms-antonyms|E|The coach praised the team's cooperation rather than any single player's skill. What is cooperation?|working together;winning easily;training alone;following silently|The contrast with one player points to shared effort.~Working together captures cooperation; a team can cooperate without winning.
vr-synonyms-antonyms|E|The museum's enormous model filled almost the entire room. Which word is closest to enormous?|huge;detailed;ancient;unusual|Filling almost the room provides a clue about size.~Huge has the same size meaning, whereas detailed and ancient describe different properties.
vr-synonyms-antonyms|E|The sign prohibited feeding the birds. What did it do?|forbade it;recommended it;explained it;recorded it|To prohibit an action is to disallow it.~Forbade it is the matching meaning; explaining a practice would not necessarily ban it.
vr-synonyms-antonyms|M|The committee reached a tentative agreement, pending a check of the costs. Tentative most nearly means what?|provisional;unanimous;expensive;secret|The agreement still depends on a later cost check.~Provisional means subject to confirmation; unanimous says who agreed, which is not supplied.
vr-synonyms-antonyms|E|Ari gave a concise account of the trip, omitting every unnecessary detail. Which word best replaces concise?|brief;careless;uncertain;cheerful|The omission of unnecessary detail signals economical expression.~Brief fits; careless would suggest errors rather than controlled brevity.
vr-synonyms-antonyms|M|The evidence was sufficient to support a small trial, though not a full launch. Sufficient means what?|enough;conclusive;abundant;irrelevant|The evidence meets the threshold for the limited trial.~Enough is the precise meaning; conclusive would claim stronger certainty than the sentence allows.
vr-synonyms-antonyms|E|Jade devised a way to collect the spilled seeds without crushing them. Devised means what?|thought up;copied down;gave away;put aside|The sentence credits Jade with creating a method.~Thought up expresses invention; copying down would merely record somebody else's method.
vr-synonyms-antonyms|M|The instructions were ambiguous, so two groups assembled the parts differently. Ambiguous most nearly means what?|open to more than one interpretation;too lengthy to finish;deliberately false;written in another language|Two different constructions suggest multiple reasonable readings.~The first choice describes ambiguity; length, dishonesty and language are not established.
vr-synonyms-antonyms|M|The volunteers salvaged timber from the damaged shed. What did they do to the timber?|recovered it for use;measured it precisely;burned it safely;ordered replacements|The source is a damaged structure, but the timber is retrieved.~Recovering material for use is salvage; replacement timber would come from elsewhere.
vr-synonyms-antonyms|M|Maya's meticulous notes included dates, measurements and tiny changes in colour. Meticulous means what?|very careful;highly imaginative;quickly written;difficult to read|The detailed observations indicate close care.~Very careful captures meticulous; imagination and speed do not account for accurate small details.
vr-synonyms-antonyms|M|The council deferred its decision until the residents' survey was complete. Deferred means what?|postponed;reversed;announced;delegated|The decision is moved to a later time rather than made immediately.~Postponed is the matching action; delegated would transfer responsibility to someone else.
vr-synonyms-antonyms|E|A nearby building obscured our view of the comet. Obscured most nearly means what?|blocked;improved;framed;reflected|The building prevents a clear view.~Blocked fits the obstruction; framed would leave the object visible within a boundary.
vr-synonyms-antonyms|E|The guide's reassuring voice made the unfamiliar tunnel seem less frightening. Reassuring means what?|reducing worry;giving orders;showing surprise;providing entertainment|The voice changes the visitors' fear.~Reducing worry captures reassurance, whereas giving orders concerns control rather than comfort.
vr-synonyms-antonyms|E|The shop stocked a diverse range of seeds, from herbs to tall trees. Diverse means what?|varied;unusual;costly;local|Herbs and tall trees illustrate different kinds within the range.~Varied means containing different types; local describes origin and does not express variety.
vr-synonyms-antonyms|M|A resilient sapling bent in the storm and grew upright again. Resilient most nearly means what?|able to recover;easily broken;fully grown;slow to change|Bending followed by renewed growth demonstrates recovery after stress.~Able to recover is the defining feature, rather than never bending at all.
vr-synonyms-antonyms|C|The review was critical of the design but critical to its improvement. In the second use, critical means what?|essential;disapproving;dangerous;uncertain|The two uses have different meanings: first disapproving, then necessary.~Essential fits the second use because the review helps improvement; transferring the first meaning would misread the contrast.
vr-synonyms-antonyms|C|The speaker qualified her claim by adding, 'only in dry weather'. Qualified here means what?|limited its scope;proved it completely;made it more impressive;earned permission to make it|The extra condition restricts when the claim applies.~Limited its scope fits; the sporting or credential meaning of qualified is irrelevant here.
vr-synonyms-antonyms|C|The proposal was sound, although the hall's sound system failed during its presentation. The first sound means what?|well founded;audible;loud;musical|The first use evaluates the quality of the proposal rather than noise.~Well founded is the appropriate sense; the later sound system creates a tempting but unrelated auditory meaning.
vr-synonyms-antonyms|C|Nora remained reserved at the gathering, but nobody had reserved a seat for her. The first reserved means what?|restrained in manner;kept for later;already booked;excluded from the event|The first word describes Nora's behaviour.~Restrained in manner fits her social manner; the second use means booked and should not determine the first.
vr-synonyms-antonyms|C|The historian questioned the account, not because it was impossible, but because it lacked corroboration. Corroboration means what?|independent supporting evidence;a clear sequence of events;an interesting viewpoint;formal publication|The issue is whether another source supports the account.~Independent supporting evidence provides corroboration; publication alone does not verify a claim.
vr-synonyms-antonyms|C|The solution was elegant: one small change solved several connected problems. Elegant here most nearly means what?|simple and effective;fashionably decorated;carefully concealed;expensive to produce|One change achieving several results indicates economy and effectiveness.~Simple and effective captures this technical sense; decorative elegance is a different meaning.
vr-synonyms-antonyms|C|The witness gave a plausible explanation, but the investigator still sought proof. Plausible means what?|seemingly reasonable;certainly true;deliberately misleading;completely original|The explanation could reasonably be true, but proof remains missing.~Seemingly reasonable preserves that uncertainty; certainly true would contradict the investigator's need for proof.
vr-synonyms-antonyms|C|The article's title was deliberately understated: 'A small delay' described a journey postponed for a year. Understated means what?|expressed as less significant than it was;explained without any evidence;described in precise technical terms;repeated more often than needed|Calling a year-long postponement small reduces its apparent scale.~The first choice captures that deliberate mismatch, rather than implying the title is technical or repetitive.
vr-synonyms-antonyms|C|The mayor's response was evasive: she described the weather instead of answering the budget question. Evasive means what?|avoiding a direct answer;offering a careful estimate;admitting an error openly;rejecting the question as false|The change of subject leaves the budget issue unanswered.~Avoiding a direct answer matches evasive; there is no estimate, admission or explicit rejection.
vr-synonyms-antonyms|C|The prediction was conservative, allowing for delays rather than assuming everything would go well. Conservative here means what?|cautious in its estimate;opposed to all change;based on old equipment;lower than every earlier result|The description concerns a forecast that accounts for setbacks.~Cautious in its estimate fits this use; the sentence does not establish political views or a comparison with all earlier results.
vr-synonyms-antonyms|C|The runner's lead was marginal; the photograph showed only a few centimetres between them. Marginal means what?|very slight;near the edge of the track;steadily growing;impossible to measure|The photograph identifies a small but real difference.~Very slight fits the size of the lead; the track-edge meaning of margin is not relevant.
vr-synonyms-antonyms|C|The new timetable made the old notice redundant. Redundant means what?|no longer needed;harder to understand;unreliable from the start;more widely available|The new information replaces the old notice's function.~No longer needed captures redundancy; the old notice may have been reliable before the change.
vr-synonyms-antonyms|C|A lucid explanation enabled the pupils to reconstruct the experiment themselves. Lucid most nearly means what?|clear and understandable;very brief and incomplete;surprising and amusing;confident but unsupported|The explanation lets the pupils understand enough to repeat the process.~Clear and understandable matches that result; confidence without clarity would not establish understanding.
vr-synonyms-antonyms|C|The judge called the second design derivative because it closely followed an earlier entry. Derivative means what?|based heavily on existing work;calculated using numbers;made with inferior materials;developed by several people|The reason given is dependence on a previous design.~Based heavily on existing work captures the artistic meaning; the mathematical sense is a distracting alternative.
vr-synonyms-antonyms|C|The report distinguished a correlation from a cause. Correlation most nearly means what?|an association between changes;proof that one event produces another;a mistake in collecting results;a prediction with no observations|An association means variables change together without establishing why.~The first choice preserves the distinction; claiming proof of production would confuse association with cause.
vr-synonyms-antonyms|C|The director's praise was tempered by a warning that rehearsals still needed work. Tempered means what?|moderated;withdrawn entirely;made angrier;repeated more loudly|The warning limits how unqualified the praise is.~Moderated fits praise mixed with caution; the praise is not necessarily cancelled or turned into anger.
vr-synonyms-antonyms|C|The curator wanted a representative sample of local craft, rather than only the most expensive pieces. Representative means what?|reflecting the wider range;chosen by elected officials;more valuable than average;produced in the same year|The contrast is between a balanced sample and a narrow costly subset.~Reflecting the wider range fits; political representation is a separate sense.
vr-synonyms-antonyms|C|The two accounts were compatible even though they emphasised different details. Compatible means what?|able to be true together;identical in every respect;equally detailed;written by the same person|Different emphasis does not necessarily create a contradiction.~Able to be true together expresses compatibility without claiming complete identity.
vr-synonyms-antonyms|C|The editor removed a superfluous paragraph that merely repeated the introduction. Superfluous means what?|unnecessary;inaccurate;misleading;unfinished|Repetition without a new purpose explains why the paragraph is removed.~Unnecessary captures the issue; repeated information can still be accurate and complete.
vr-synonyms-antonyms|C|The pilot study indicated a possible benefit, but its findings were inconclusive. Inconclusive means what?|not settling the question;proving there is no benefit;too confusing to describe;unrelated to the question|A possible benefit falls short of a settled result.~Not settling the question allows further evidence either way; absence of certainty is not proof of no benefit.
vr-synonyms-antonyms|E|The road was smooth before the storm and rough afterwards. Which word is opposite to rough in this comparison?|even;fragile;steep;narrow|The contrast concerns the road's surface texture.~Even describes a smooth surface, whereas steep concerns slope and narrow concerns width.
vr-synonyms-antonyms|E|The puppy was timid with visitors. Which word would reverse the meaning of timid?|bold;small;quiet;gentle|Timid describes a lack of confidence around others.~Bold reverses that attitude; small and gentle can describe even a confident puppy.
vr-synonyms-antonyms|E|The room was vacant until the class arrived. Which word is opposite to vacant here?|occupied;crowded;enclosed;private|Vacant means no one occupies the room.~Occupied is the exact opposite; crowded is a stronger condition and is not required to reverse vacancy.
vr-synonyms-antonyms|E|The teacher gave an explicit instruction. Which word would describe the opposite kind of instruction?|implied;detailed;helpful;unusual|Explicit means stated directly.~Implied means left to be inferred, reversing directness rather than clarity of layout or helpfulness.
vr-synonyms-antonyms|M|The plants were abundant beside the creek but ____ on the rocky ridge. Which word completes the strongest contrast?|scarce;fragile;dormant;similar|Abundant refers to plentiful numbers.~Scarce reverses that quantity; fragile concerns strength and dormant concerns activity.
vr-synonyms-antonyms|M|An impartial judge must avoid being ____. Choose the word that reverses impartial.|biased;strict;patient;experienced|Impartial means free from favouritism.~Biased is its opposite; a strict or experienced judge may still be fair.
vr-synonyms-antonyms|M|The guide called the shortcut hazardous. Which description gives the opposite meaning?|safe to use;easy to find;quick to follow;rarely visited|Hazardous refers to danger, not distance or popularity.~Safe to use reverses the risk meaning; an easy-to-find route can still be dangerous.
vr-synonyms-antonyms|M|The first signal was intermittent; the second was ____. Which word creates the clearest opposite?|continuous;powerful;distant;electrical|Intermittent means stopping and starting.~Continuous means unbroken, reversing the timing property without making a claim about strength.
vr-synonyms-antonyms|M|A flexible rule can be adjusted. Which word describes its opposite?|rigid;simple;public;recent|The defining feature is adaptability.~Rigid means not readily adjusted; a simple rule may still be flexible.
vr-synonyms-antonyms|E|The reply was courteous despite the complaint. Which word would reverse courteous?|rude;brief;firm;honest|Courtesy concerns politeness.~Rude reverses it, while firmness, brevity and honesty can all coexist with politeness.
vr-synonyms-antonyms|M|The team will expand the project this year. Which action is the opposite of expand?|reduce its scope;delay its start;change its leader;review its purpose|Expansion increases size or scope.~Reducing scope reverses that growth; delay changes timing rather than size.
vr-synonyms-antonyms|M|The water was transparent before mud entered it. Which word best gives the opposite of transparent?|opaque;shallow;cold;still|Transparent means light passes through so objects can be seen.~Opaque blocks that view; the other choices describe unrelated water properties.
vr-synonyms-antonyms|M|An optimistic forecast expects good results. Which word reverses optimistic?|pessimistic;realistic;precise;detailed|Optimism concerns expecting favourable outcomes.~Pessimistic reverses that expectation; a realistic forecast could be either favourable or unfavourable.
vr-synonyms-antonyms|M|The speech united the group. Which word describes the opposite effect?|divided;surprised;informed;silenced|Uniting brings people together.~Dividing separates them into opposing groups; silence or surprise does not necessarily undo unity.
vr-synonyms-antonyms|C|The journalist sought to corroborate the rumour. Which action moves most directly in the opposite evidential direction?|discredit it;publish it;repeat it;qualify it|Corroborating adds support to a claim.~Discrediting undermines its reliability. Qualifying only limits scope and need not remove support.
vr-synonyms-antonyms|C|The instructions encouraged a literal reading of the phrase. Which word best reverses literal in this context?|figurative;careful;accurate;formal|A literal reading uses the ordinary direct meaning.~Figurative uses a transferred or imaginative meaning; it can still be careful and accurate as interpretation.
vr-synonyms-antonyms|M|The scientist called the effect reversible. Which phrase states the opposite precisely?|unable to be undone;unlikely to happen again;slow to appear;hard to notice|Reversibility concerns whether a change can be undone.~Unable to be undone reverses that property; repetition and visibility are separate matters.
vr-synonyms-antonyms|C|The reporter's account was objective. Which word gives the strongest opposite when describing its viewpoint?|subjective;personalised;detailed;unpopular|Objective reporting aims to separate evidence from personal judgement.~Subjective reporting depends on a personal viewpoint; being detailed or unpopular does not determine objectivity.
vr-synonyms-antonyms|C|The plan was feasible within the available budget. Which word reverses feasible?|impracticable;unusual;costly;unpopular|Feasible means capable of being carried out under the conditions.~Impracticable reverses that capability; costly can still be feasible if funds are available.
vr-synonyms-antonyms|M|An inclusive invitation welcomed every member. Which phrase gives the opposite approach?|excluding some members;addressing members individually;requiring replies early;describing several activities|Inclusiveness concerns who is allowed to take part.~Excluding some members directly reverses that scope; an individual or early-reply invitation may still welcome everyone.
''')

verbal(r'''
vr-analogies|E|A compass indicates direction; a thermometer indicates what?|temperature;distance;pressure;weight|The relationship is instrument to quantity indicated.~A thermometer indicates temperature; the other choices require different instruments.
vr-analogies|M|A rehearsal prepares a performance as a trial run prepares a ____. Choose the closest matching relationship.|procedure;audience;costume;review|A rehearsal is a practice execution before the main event.~A trial run similarly prepares a procedure; an audience is a recipient rather than the practised activity.
vr-analogies|M|A root anchors a tree as a foundation anchors a ____.|building;builder;brick;roof tile|The root supports and secures the whole tree.~The foundation serves that role for a building, rather than for an individual worker or component.
vr-analogies|C|An index helps a reader locate a topic within a book. Which pair has the same guide-to-location relationship?|directory : office;cover : book;author : sentence;ticket : journey|An index points to the location of information rather than containing the whole subject.~A directory points to an office location. A cover encloses a book and a ticket permits travel, so their functions differ.
vr-analogies|M|A curator selects works for an exhibition. A compiler selects entries for an ____.|anthology;auditorium;easel;applause|The relationship is selector to assembled collection.~A compiler gathers entries into an anthology; an auditorium is a venue rather than a collection.
vr-analogies|C|A map simplifies a landscape; a summary simplifies an ____. Preserve the representation-to-source relationship.|account;opinion;author;alphabet|A map is a reduced representation of the landscape.~A summary is a reduced representation of a longer account; an author creates a source rather than being the source content.
vr-analogies|M|Seed is to germination as egg is to ____. Choose the matching developmental event.|hatching;nesting;laying;flying|Germination is the event in which the young plant emerges from a seed.~Hatching similarly releases the young animal from an egg; laying precedes the egg's development.
vr-analogies|C|A hypothesis is tested by evidence as an accusation is tested by ____. Choose the best parallel rather than a guaranteed outcome.|investigation;punishment;disagreement;suspicion|A hypothesis needs examination against evidence before acceptance.~An accusation similarly needs investigation. Punishment assumes a conclusion and suspicion does not test it.
vr-analogies|M|Editor is to manuscript as restorer is to ____. Match the object improved by the specialist.|painting;gallery;brush;visitor|An editor works on a manuscript to improve its condition or quality.~A restorer works on a painting; a brush is a tool and a gallery is a location.
vr-analogies|C|A blueprint precedes construction as an outline precedes ____. Choose the planned product or process.|composition;revision;publication;quotation|A blueprint guides the creation process.~An outline guides composition. Revision comes after an initial composition and publication is a later distribution step.
vr-analogies|M|Evaporation changes liquid to gas. Freezing changes liquid to ____.|solid;vapour;heat;mist|Both words describe a change in physical state.~Freezing produces a solid; mist consists of liquid droplets and is not the frozen state.
vr-analogies|C|A rebuttal responds to an argument as an antidote responds to a ____. Match the counteracting function.|poison;doctor;symptom;diagnosis|A rebuttal attempts to counter an argument's force.~An antidote counteracts poison; diagnosis identifies a problem and a symptom is an effect rather than the target substance.
vr-analogies|M|A milestone marks progress through a journey. Which item most closely marks progress through a project?|checkpoint;deadline;budget;proposal|A milestone is a point at which progress can be judged.~A checkpoint performs that function in a project. A deadline marks a required completion time rather than necessarily measuring progress along the way.
vr-analogies|C|A password restricts access to an account. Which pair most closely shares that function-to-target relationship?|key : locked cabinet;label : parcel;stamp : envelope;handle : door|The first item is needed to gain permitted access to the second.~A key controls access to a locked cabinet; a handle operates a door but does not itself restrict access.
vr-analogies|M|A glossary explains specialised words as a legend explains symbols on a ____.|map;dictionary;speech;calendar date|Both aids explain compact forms used in a larger work.~A legend explains a map's symbols; a dictionary explains words and would duplicate the first side instead.
vr-analogies|C|Scaffolding supports a building while it is being constructed. Which pair has the closest temporary-support relationship?|training wheels : learning cyclist;helmet : cyclist;signpost : road;engine : vehicle|The defining relation is support used during development and later removed.~Training wheels help a learning cyclist and can later be removed; helmets remain protective equipment after learning.
vr-classification|E|Which word does not belong with cedar, willow and birch when the group is defined as kinds of tree?|fern;oak;maple;elm|Cedar, willow and birch are trees.~Fern is a different plant group; oak, maple and elm would all fit the stated tree category.
vr-classification|M|Which item cannot join a group of instruments that measure a physical quantity: barometer, odometer, thermometer?|telescope;speedometer;hygrometer;ammeter|Each listed instrument gives a measurement such as pressure, distance or temperature.~A telescope primarily magnifies distant objects; the other choices measure speed, humidity and electric current.
vr-classification|M|The words whisper, murmur and mutter describe quiet vocal actions. Which choice does not fit that defined group?|bellow;mumble;speak softly;speak under one's breath|The defining quality is low-volume vocal expression.~Bellow means shout loudly and breaks that volume pattern; the other choices are quiet actions.
vr-classification|C|A set contains prediction, forecast and projection in their future-estimate senses. Which word is least suitable for that set?|recollection;expectation;anticipation;outlook|The members concern what may happen later.~Recollection concerns the past, while the other choices can all concern future expectations.
vr-classification|M|Which word names a process rather than the product in this list: sculpture, engraving, portrait, statue? Treat engraving as the action of cutting a design.|engraving;sculpture;portrait;statue|The instruction fixes the otherwise ambiguous sense of engraving.~In that sense it is an action; the remaining words name finished works or objects.
vr-classification|C|Choose the word that is not a degree of certainty: possible, probable, certain, chronological.|chronological;possible;probable;certain|Possible, probable and certain indicate different confidence levels.~Chronological describes time order rather than confidence, even if a chronological account is reliable.
vr-classification|M|Which is not a means of preserving food: drying, freezing, canning, garnishing?|garnishing;drying;freezing;canning|The first three listed methods aim to extend storage life.~Garnishing decorates food for presentation and does not serve that preservation function.
vr-classification|C|When classifying argument moves, which differs from the other three: providing a counterexample, disproving a premise, exposing a contradiction, restating the conclusion?|restating the conclusion;providing a counterexample;disproving a premise;exposing a contradiction|Three moves can challenge the support for an argument.~Merely restating its conclusion does not test its support and is therefore the different move.
vr-classification|M|Which term refers to a person who receives a message rather than creates or carries it: author, sender, courier, recipient?|recipient;author;sender;courier|Author and sender originate a message; courier carries it.~Recipient names the person at the receiving end, distinguishing role rather than job importance.
vr-classification|C|Which word describes a relationship between two things rather than a property one thing can have alone: heavier, fragile, porous, brittle?|heavier;fragile;porous;brittle|Heavier makes a comparison, even if the compared object is left unstated.~The other properties can be described without a second object, so they belong to a different logical category.
vr-classification|M|Choose the non-renewable resource from sunlight, wind, coal and flowing water.|coal;sunlight;wind;flowing water|Sunlight, wind and flowing water are replenished by continuing natural processes on human timescales.~Coal forms over geological timescales and is depleted by use, making it non-renewable.
vr-classification|C|Which term concerns the arrangement of events rather than the narrator's attitude: chronology, scepticism, admiration, nostalgia?|chronology;scepticism;admiration;nostalgia|Scepticism, admiration and nostalgia describe attitudes or feelings.~Chronology concerns event order; it can be used with any of those attitudes.
vr-sentence-logic|E|Every lantern in the display uses a battery. The small red object is a lantern in the display. What must it use?|a battery;a candle;a red battery;two batteries|The rule applies to every lantern in this display, including the identified object.~A battery necessarily follows; colour and number of batteries are not stated.
vr-sentence-logic|M|Only ticket holders may enter the balcony. Suri entered the balcony with permission. Which conclusion follows?|Suri held a ticket;all ticket holders entered;Suri bought the ticket;Suri sat in the front row|Only ticket holders may enter makes holding a ticket necessary for permitted entry.~Suri's permitted entry therefore implies a ticket, without specifying how it was acquired or where she sat.
vr-sentence-logic|C|All flints are stones. Some stones are polished. Which statement must follow?|No flint is outside the stone group;some flints are polished;all stones are flints;no polished object is a flint|The first rule includes every flint among stones.~The polished stones might or might not be flints. Only the inclusion of all flints in the stone group is guaranteed.
vr-sentence-logic|M|If the archive is open, the green light is on. The green light is off. What follows from these rules?|the archive is not open;the archive has no power;the archive opens tomorrow;the green light is broken|An open archive would require the light to be on.~Because the light is off, the archive cannot be open under the rule. The cause and future opening are unknown.
vr-sentence-logic|C|Whenever Ivo paints, he wears an apron. Today he wears an apron. Which statement is justified?|He may be painting, but need not be;he must be painting;he cannot be painting;he paints only today|The rule gives painting implies apron, not apron implies painting.~He could wear the apron for another reason, so painting remains possible but unproved.
vr-sentence-logic|M|No reptiles in the rescue centre have feathers. Kito is a reptile there. Which conclusion is certain?|Kito has no feathers;Kito cannot swim;all featherless animals are reptiles;Kito lives outside|Kito belongs to the group covered by the no-feathers rule.~Nothing is stated about swimming or housing, and reversing the rule would be invalid.
vr-sentence-logic|C|Some sculptors are gardeners. Every gardener in this town owns gloves. Which statement must be true about those people?|Some sculptors own gloves;all sculptors own gloves;every glove owner is a gardener;no sculptor lacks gloves|The sculptors who are also gardeners fall under the glove rule.~At least those sculptors own gloves; the rule says nothing about the remaining sculptors or non-gardener glove owners.
vr-sentence-logic|M|A library loans an atlas only if the borrower leaves a deposit. Tessa borrowed an atlas. What must have happened?|Tessa left a deposit;Tessa paid a fee;Tessa borrowed no other book;Tessa owns an atlas|Only if makes the deposit a required condition.~Borrowing the atlas therefore entails a deposit, but not a fee or a restriction on other loans.
vr-sentence-logic|C|No amber boxes are heavy. All boxes on the bottom shelf are heavy. Which conclusion follows?|No amber box is on the bottom shelf;all heavy boxes are on the bottom shelf;all amber boxes are on the top shelf;some bottom-shelf boxes are amber|An amber box cannot be heavy, while any bottom-shelf box must be heavy.~Those groups cannot overlap. Exclusion from the bottom shelf does not identify a particular other shelf.
vr-sentence-logic|M|The badges go to either the science group or the art group, but not both. The science group receives them. What follows?|The art group does not receive them;the art group receives different badges;the science group made them;neither group receives them|The rule explicitly excludes joint receipt.~Once the science group receives these badges, the art group cannot receive the same allocation; no other allocation is described.
vr-sentence-logic|C|At least one runner is a violinist. No violinist in the group is a swimmer. What must be true?|At least one runner is not a swimmer;no runner is a swimmer;all swimmers are runners;some violinists are swimmers|Take the runner who is also a violinist.~The exclusion rule prevents that person from being a swimmer, but other runners could swim.
vr-sentence-logic|M|If a parcel exceeds 2 kg, it receives a yellow label. This parcel has no yellow label. Under the rule, what can its mass be?|2 kg or less;more than 2 kg;exactly 1 kg;less than 0.5 kg|A mass above two kilograms would force a yellow label.~Its absence rules out above two, but does not narrow the mass to one specific value below or at two.
vr-sentence-logic|C|All members of the morning choir attend rehearsal. No one who attends rehearsal can join the trip at that time. Which conclusion follows?|No morning-choir member can join that trip;everyone outside the choir can join;all trip members dislike singing;no choir member can ever travel|Choir membership implies rehearsal, which excludes the simultaneous trip.~The conclusion is limited to that trip and time; the rules do not exclude other obstacles or later travel.
vr-sentence-logic|M|Either the key is in the drawer or it is in the bag. It is not in the drawer. What follows?|It is in the bag;it is in both places;the bag is locked;someone moved it|The two listed locations exhaust the possibilities under the premise.~Eliminating the drawer leaves the bag; no conclusion about movement or locking follows.
vr-sentence-logic|C|Exactly one of these statements is true: 'The parcel is heavy' and 'The parcel is fragile'. The parcel is fragile. What follows?|The parcel is not heavy;the parcel is heavy;all fragile parcels are light;the parcel must be small|Exactly one true statement excludes both being true.~Since fragile is true, heavy is false for this parcel only; the rule does not describe all fragile parcels.
vr-sentence-logic|C|All cedar tokens are round. No round token fits the narrow slot. Some wooden tokens are cedar. Which statement is forced?|Some wooden tokens do not fit the narrow slot;no wooden token fits any slot;every round token is cedar;some cedar tokens fit the narrow slot|The wooden tokens that are cedar are round, so they cannot fit this slot.~This establishes a statement about some wooden tokens, without extending it to all wooden tokens or all slots.
vr-coded-words|E|A code replaces each letter with the next letter of the alphabet, with Z followed by A. How is MAP coded?|NBQ;LZO;MBQ;OBR|Advance M to N, A to B and P to Q.~Writing those replacements in order gives NBQ; reversing the alphabet direction would give LZO.
vr-coded-words|M|In a code, letters move two places backwards, wrapping before A to Z. What is the code for CAVE?|AYTC;ECXG;AZUD;B Z U D|Move C to A, A to Y, V to T and E to C.~The result is AYTC. The wrap at A is essential and the shift applies to every letter.
vr-coded-words|C|A code reverses a word and then advances every letter by one, with Z followed by A. How is BARK coded?|LSBC;CBSL;JQZA;LSCB|Reverse BARK to KRAB before changing letters.~K becomes L, R becomes S, A becomes B and B becomes C, giving LSBC. Coding without reversal would give CBSL.
vr-coded-words|M|A code changes vowels A E I O U to 1 2 3 4 5 and leaves consonants unchanged. What is the code for EQUIP?|2Q53P;2Q35P;1Q53P;2Q5IP|In EQUIP, E becomes 2, U becomes 5 and I becomes 3.~Keep Q and P in place to get 2Q53P; the order of the vowel values follows the word.
vr-coded-words|C|To code a word, swap the first and last letters, then move the new first letter two alphabet places forward. Do not change other letters. What is the code for LAMP?|R A M L;N A M P;P A M L;R L M A|Swapping the ends of LAMP gives PAML.~Move only the new first letter P forward two places to R, producing RAML, shown with spaces as R A M L.
vr-coded-words|M|Letters are replaced by alphabet positions: A=1 through Z=26. What is the sum of the code numbers for DUSK?|55;54;56;58|The letter values are D=4, U=21, S=19 and K=11.~Their sum is 55; fifty-five combines all four letter values.
vr-letter-series|M|Letters in a pattern advance by 2, then 3, then 4 positions: B, D, G, K. What follows if the advance increases by one again?|P;O;Q;R|The changes are +2, +3 and +4 alphabet places.~The next change is +5; moving five places after K gives P.
vr-letter-series|C|Two letter sequences are interleaved: A, Z, C, X, E, V, G, ?. What is missing?|T;H;U;S|The odd positions advance A, C, E, G by two.~The even positions retreat Z, X, V by two, so the next even-position letter is T.
vr-letter-series|M|A row gives letter pairs AZ, BY, CX, DW. The first letter moves forward and the second backward by one. Which pair comes next?|EV;EU;FV;EX|Continue the first letters A through E and second letters Z through V.~The next pair is EV, moving both sides in their stated directions.
vr-letter-series|C|A pattern alternates letters at positions n and 27-n in the alphabet: C, X, F, U, I, R, L, ?. First letters in each pair advance by three. What is missing?|O;M;N;P|The complementary pairs have position sums 27: C/X, F/U and I/R.~L has position 12, so its partner has position 15, which is O.
vr-word-relationships|M|Which word can complete both phrases meaningfully: 'a ____ of lightning' and 'a door ____'?|bolt;flash;lock;beam|A bolt of lightning names an electrical flash.~A door bolt is a fastening. Flash fits the first phrase but not the second in the intended everyday sense.
vr-word-relationships|C|Choose the single word that can mean both 'a formal statement of charges' and 'a proposed law'.|bill;claim;order;notice|A bill can state an amount charged for goods or services.~A bill is also a proposed law before enactment; claim and notice do not share both conventional senses.
''')

reading('The spare seat', '''
At the first rehearsal, Anika chose a chair in the back row. From there she could watch the violin bows without anyone watching hers. When the conductor asked for a volunteer to play the opening phrase, she bent to retie a perfectly secure shoelace.

On Thursday a new player arrived carrying a battered case. The only empty chair stood beside Anika. He opened his music upside down, noticed, and laughed. 'I hoped nobody would see that,' he said. Anika showed him where to begin.

During the break he asked her to play the opening slowly so he could follow. She played it twice, stumbling once. He thanked her anyway. After the break, the conductor asked again for a volunteer. Anika's hand moved before she had time to study her shoelace.

Her first note trembled. From the chair beside her came a small, steady tap of a shoe keeping time. The rest of the phrase followed. Afterwards, she left her music on the chair while she fetched water. She was saving the seat, but no longer hiding in it.
''',r'''
factual-retrieval|E|In 'The spare seat', why does the new player ask Anika to play slowly?|so he can follow the opening;so the conductor can leave;because her violin is damaged;because the rehearsal is over|He explicitly asks her to play the opening slowly so he can follow.~The request is for help learning the music, rather than a judgement about her instrument.
character-inference|M|What does Anika's shoelace action at the first rehearsal suggest?|She wants to avoid volunteering;she cannot see the conductor;she is preparing to leave;she has forgotten her music|The shoelace is described as perfectly secure and she bends when a volunteer is requested.~The unnecessary action provides a way to avoid being selected.
cause-effect|M|Which experience most directly prepares Anika to volunteer on Thursday?|helping the new player with the phrase;being given a different violin;hearing the conductor praise her publicly;moving to the front row|She has just played for the new player, including a stumble, and still receives thanks.~That safe experience plausibly builds confidence; the other events do not occur in the text.
authorial-craft|C|Why does the final sentence distinguish saving the seat from hiding in it?|It reinterprets the same location as companionship rather than avoidance;it proves she will always play solos;it explains why the chair is empty;it suggests the conductor should move the chairs|The opening uses the back chair as protection from notice, while the ending connects it to the new player.~The physical seat stays the same but its emotional function changes.
factual-inference|C|Which statement best respects both Anika's trembling note and her completed phrase?|She acts despite remaining nervous;she has entirely lost her fear;she relies on the new player to play her notes;she finds the music technically easy|The first note still trembles, showing nerves have not disappeared.~She nevertheless finishes the phrase, so progress means acting through anxiety rather than eliminating it.
''')

reading('A cooler courtyard', '''
The following account describes a fictional school investigation. Students wanted to know whether two courtyard surfaces warmed differently in sunlight. They placed identical thermometers on a dark rubber mat and pale paving at 10 am. Both surfaces began at 19 degrees. At noon the mat read 34 degrees and the paving 28 degrees. At 2 pm a cloud covered the courtyard; both readings fell.

One pupil proposed replacing every dark surface immediately. The teacher asked whether one afternoon could settle the decision. The mat lay near a warm wall, while the paving was exposed to a light breeze. The students had measured temperature on the surfaces, not the air where people walked.

For a second trial they planned to exchange the thermometers, measure several days and choose locations equally sheltered from wind. They would also compare the cost and durability of possible replacements. Their first results were useful: they provided a reason to investigate further. They did not yet provide a complete purchasing plan.
''',r'''
factual-retrieval|E|At noon in 'A cooler courtyard', what was the temperature difference between the surfaces in degrees?|6;9;15;34|The mat read 34 degrees and the paving 28 degrees at noon.~Subtract 28 from 34 to obtain six degrees; the starting reading is not used for this comparison.
factual-inference|M|Why might the nearby wall complicate the courtyard comparison?|It could warm the mat independently of surface colour;it prevents any thermometer from working;it proves the paving is cooler every day;it changes the starting time|The mat is near a warm wall, while the paving has a breeze.~These unequal conditions could contribute to the difference, so colour is not isolated as the sole cause.
argument-evaluation|C|Which conclusion is best supported by the first courtyard trial?|The mat was hotter at noon under those conditions;all dark surfaces should be removed;surface temperature equals air temperature;the mat will always heat faster than paving|The recorded readings support a limited observation about that trial.~The text expressly warns about location, measurement type and the short observation period, which prevent the broader claims.
cause-effect|M|What is the purpose of exchanging thermometers in the second courtyard trial?|to check whether the instruments affect the comparison;to ensure both surfaces become identical;to make a longer day;to avoid recording the wind|Moving the instruments helps detect a consistent difference caused by the instruments themselves.~It cannot make the actual materials identical or remove all other variables.
text-structure|C|How does 'A cooler courtyard' develop its main point?|It presents findings, questions their limits and proposes a stronger investigation;it lists costs before arguing against measurement;it compares two complete purchasing plans;it describes a failed experiment with no useful result|The first paragraph records observations, the second identifies limits and the third plans improvements.~This sequence treats preliminary evidence as useful without presenting it as final proof.
''')

reading('Letter about the vacant block', '''
Dear councillors,

Before the vacant block beside the library becomes a car park, please trial a small community garden there for one year. The soil need not be dug: raised containers could stand above the ground while a soil assessment is completed. A local group has offered containers and volunteers, although water and insurance would still cost money.

I understand the concern about parking. On market Saturdays, visitors sometimes circle the block twice. But the proposed car park would provide only twelve spaces, and the market operates just twice a month. A garden could support weekly classes and a shaded place to meet on other days.

A trial would not remove every uncertainty. Volunteers may lose interest, and containers need summer watering. That is why I suggest publishing costs and attendance after six months, with a clear decision at the end of the year. If the trial fails, the containers can be moved. Let us choose using local evidence rather than assuming either project must be permanent from its first day.

Yours sincerely,
Ruth Ellis
''',r'''
main-idea|E|What does Ruth mainly request in her letter about the vacant block?|a one-year garden trial;an immediate permanent ban on cars;a larger market every week;the demolition of the library|Her opening request is a small community garden trial for one year.~The rest of the letter supports and limits that request rather than asking for permanent exclusion of cars.
factual-retrieval|M|Which garden cost is still needed despite the offered containers and volunteers?|water and insurance;the purchase of every container;payment to every volunteer;moving the library|The first paragraph explicitly says water and insurance would still cost money.~The donated resources reduce some costs but do not eliminate those named expenses.
argument-evaluation|C|Why does Ruth mention twelve spaces and a twice-monthly market?|to question whether parking benefits justify permanent use of the whole block;to prove nobody needs parking;to calculate the garden's exact profit;to promise the trial will solve traffic|She acknowledges parking pressure, then limits its scale and frequency.~Those details support comparing uses; they do not prove parking demand is absent or that the garden solves it.
tone-analysis|M|Which description best fits Ruth's tone towards concerns about the garden?|supportive but realistic;mocking and dismissive;certain of unlimited funding;indifferent to the outcome|Ruth supports the garden while recognising watering, insurance and volunteer risks.~That combination is realistic advocacy rather than mockery or certainty.
authorial-craft|C|What role does the proposal to move the containers play in Ruth's argument?|It shows the trial can be reversed;it guarantees the garden will attract visitors;it removes the need for soil assessment;it proves a car park costs more|Movable containers reduce the commitment required to try the garden.~They answer the permanence concern without guaranteeing attendance or settling unrelated cost and soil questions.
''')

reading('Night at the jetty', '''
The jetty combs the dark with wooden teeth.
A rope knocks twice against a sleeping boat.
Across the bay, a window holds its breath;
then someone draws a curtain on its light.

I came to see the boats return like stars,
each yellow lamp a promise moving home.
But now the tide has folded up the sand,
and all the fishing boats are tied and still.

My grandfather once knew them by their sounds:
the gruff old engine, and the bell that skipped.
I cannot name a single boat by ear.
I count the knocks until the rope falls quiet.

At last I turn. Behind me, in the dark,
the water keeps a language I am learning.
''',r'''
figurative-language|M|In 'Night at the jetty', what are the jetty's wooden teeth most likely to represent?|its projecting wooden supports or boards;actual animal teeth beneath the water;lamps tied to boats;the grandfather's tools|The jetty is described through a comb-and-teeth image.~The image maps the structure's repeated wooden parts onto teeth; it does not introduce a literal animal.
factual-retrieval|E|When the speaker observes the boats in the poem, what are they doing?|remaining tied and still;returning from fishing;leaving in a storm;crossing the bay in pairs|The second stanza says all the fishing boats are tied and still.~Their imagined return is what the speaker came to see, not what happens during the visit.
character-inference|C|What does the contrast with the grandfather suggest about the speaker?|The speaker is less familiar with the boats but wants to learn;the speaker distrusts the grandfather's memory;the speaker can identify every engine;the grandfather disliked the jetty|The grandfather identified boats by sound while the speaker cannot yet do so.~The final line describes learning, suggesting an emerging connection rather than rejection or mastery.
authorial-craft|C|Why does the poem repeatedly draw attention to sounds such as rope knocks, engines and a bell?|They connect the speaker's listening with the grandfather's knowledge;they show the bay is crowded with people;they provide exact instructions for fishing;they establish that the boats are damaged|The grandfather's knowledge is auditory, and the speaker counts knocks while listening.~Repeated sounds make that comparison central to the speaker's developing understanding.
tone-analysis|M|Which pair best describes the mood at the end of 'Night at the jetty'?|quiet and curious;triumphant and boastful;angry and impatient;frantic and fearful|The speaker turns away after a quiet visit and calls the water's sounds a language being learned.~That ending conveys attentive curiosity rather than victory, anger or danger.
''')

reading('The missing label', '''
'We cannot display it without a name,' said Otis, holding a smooth grey stone above the exhibition table.

'It had a label yesterday,' Mina replied. She checked the floor, then the empty packing tray. Their class collection opened in ten minutes.

Otis looked at the other stones. 'This one looks like the basalt. We can write basalt again.'

Mina shook her head. 'Looking similar is not the same as knowing. Put it beside the others with a question mark.'

'Visitors will think we forgot to finish.'

'We could tell them what we know: where it was found, how heavy it is, and which tests we still need.'

When the doors opened, a visitor stopped at their handwritten card: 'Unidentified stone. Found near the oval. Help us decide what to test next.' She spent longer there than at the neatly named samples. Otis fetched another sheet of paper. This time he wrote down her questions instead of reaching for a new label.
''',r'''
factual-retrieval|E|What is missing at the start of 'The missing label'?|the stone's identifying label;the exhibition table;all the class stones;the packing tray|The stone is present, but Mina says it had a label yesterday.~The problem is its missing identification, not the loss of the object or the whole display.
character-inference|M|What initially matters most to Otis when he suggests writing basalt again?|making the display appear complete;testing the stone's composition;learning the visitor's occupation;weighing the packing tray|He worries visitors will think the display unfinished and suggests a name based on appearance.~That response prioritises a finished presentation over confirmed identification.
argument-evaluation|C|What is Mina's strongest reason for rejecting Otis's suggested label?|Similarity alone does not establish identity;basalt cannot be grey;the stone must be valuable;visitors prefer all labels to be blank|Mina explicitly separates looking similar from knowing.~The text supplies no facts that rule out basalt; her objection concerns the evidence needed to name the stone.
cause-effect|M|Why does the visitor stop at the unidentified stone?|The card invites questions and participation;the stone has been proved rare;Otis announces a prize;the other stones have no labels|The handwritten card asks visitors to help decide what to test.~That invitation explains the exchange; rarity and a prize are never established.
authorial-craft|C|What does Otis's final action show?|He begins recording uncertainty instead of concealing it;he has identified the stone as basalt;he abandons the exhibition;he thinks Mina should stop asking questions|He records the visitor's questions rather than supplying a replacement name.~This reverses his earlier urge to fill the gap quickly and shows a change in what he values.
''')

reading('Two accounts of the same race', '''
Account A: I watched from the finish line. The runners appeared around the bend together, and Mara crossed first by less than a shoe length. She lifted both hands, then turned immediately towards Jules. From where I stood I could not hear their words. They walked back along the track side by side. The official result gave Mara first place and Jules second.

Account B: I ran beside Jules until the final bend. Earlier she had slowed when I dropped my number and helped me pick it up. After that I fell behind, so I did not see the finish clearly. When I caught up, Mara was thanking Jules for showing her how to pace the middle lap during training. Jules laughed and said, 'Next time I shall keep that trick to myself.' Then both offered to help me pin my number on more securely.

These accounts were written by different students after the fictional race. Neither writer saw and heard everything that happened.
''',r'''
factual-retrieval|E|According to Account A, who officially wins the race?|Mara;Jules;the writer of Account B;the official|Account A explicitly gives the official order as Mara first and Jules second.~Account B adds background but does not contradict that result.
factual-inference|M|Why can the writer of Account A describe the finish more directly than the writer of Account B?|The first writer is at the finish line;the first writer runs faster;the second writer forgets the result;the first writer trains Mara|Account A places the observer at the finish, while Account B says the runner fell behind and could not see it clearly.~The difference is viewpoint, not a claim about memory or training.
character-inference|C|Which statement about Jules is supported by both her actions and her final comment in Account B?|She helps others and can joke about competition;she regrets helping the fallen runner;she is certain the official result is wrong;she refuses to share any training advice|She helps with the dropped number and later offers to secure it, while joking about withholding a pacing trick.~The combination supports generosity and humour rather than resentment or refusal.
text-structure|C|What is gained by presenting both race accounts?|The second adds context beyond the first observer's reach;the second proves the first observer dishonest;the two guarantee that every detail is known;the first makes the second unnecessary|The first observes the result, while the second hears comments and describes earlier help.~Together they broaden understanding, but the final note explicitly limits both accounts.
argument-evaluation|M|Which claim would go beyond the evidence in the two accounts?|Jules deliberately let Mara win;Mara finished first;Jules helped with a dropped number;the runners knew each other from training|Neither account says Jules intentionally lost; assistance and training advice do not prove that.~The other claims are directly stated or clearly supported by the dialogue.
''')
